export type ExampleText = { english: string; chinese: string };

export const EXAMPLES: Record<string, ExampleText> = {"p02r01":{"english":"For all the encomiums & tributes the new CEO has received from the press recently, her staff have a decidedly less rosy view of her.","chinese":"尽管新任 CEO 最近从媒体那里获得了大量赞美， 她的员工对她的看法却明显不那么乐观。"},"p02r02":{"english":"Individuals, governments, and companies show ample ability to hamstring & impair themselves by setting goals based on current conditions and then blindly following them even when those conditions change drastically.","chinese":"个人 、 政府和公司通过根据当前条件设定目标并在条件发生巨大变化时仍言目遵循这些目标， 展现了极强的自我束缚能力。"},"p02r03":{"english":"Although one can adduce myriad of examples of ecosystem disruption by nonindigenous species, nevertheless most introduced species that survive in fact appear to have quite minimal & trifling effects on the ecosystem they have invaded","chinese":"尽管可以举出无数外来物种破坏生态系统的例子， 但实际上， 大多数存活下来的引入物种对其入侵的生态系统似乎彩响微乎其微。"},"p02r04":{"english":"Because the literary club often trumpeted itself as a sanctuary for temperate discussion, visitors were startled by the frequently acerbic & vitriolic tone of its recent debates.","chinese":"因为文学俱乐部经常自记为温和讨论的避风港， 访客们对其最近辩论中频繁出现的尖刻语调感到震惊。"},"p02r05":{"english":"Benjamin Franklin's reputation is so much one of appearing scientific investigation with commonsense empiricism that it is somewhat startling to realize how speculative & conjectural the great experiment's mentoring truly was.","chinese":"本杰明.富兰克林的声誉如此深植于以常识经验进行科学探究， 以至于意识到这位伟大实验的指导实际上是多么富于推测时， 令颂感意外。"},"p02r06":{"english":"Computerized facial-recognition systems can be stymied & neutralized by any number of factors, from the dirt caked on a camera lens to a hat pulled low over a subject's face.","chinese":"计算机化的面部识别系统可能会因多种因素而失效， 例如镜头上的污垢或帽子压低遮住了目标的脸。"},"p02r07":{"english":"They applaud the musicals of the 1930s and 1940s, whose plethora of stars, jokes, dances witty dialogue, and general gaiety make today's offering seem cheerless & gloomy by comparison","chinese":"他们赞扬了 20 世纪 30 年代和 40 年代的音乐副， 其众多明星 、 笑话 、 舞邑 、 机智的对话以及整体的欢快氛围， 使得当今的作品相比之下显得沉冰。"},"p02r08":{"english":"Given the important role that apologies can play in human relations and the almost daily news reports of the latest celebrity or political apology, the scarcity & want of empirical research on the subject is surprising.","chinese":"鉴于道歉在人与人关系中的重要作用， 以及几乎每天都有关于最新名人或政治道歉的新闻报道， 关于这一主题的实证研究的匮乏令人惊讶。"},"p02r09":{"english":"The television network seems to regard its longest-running comedy show as inviolable & sacrosanct, keeping it in the schedule even as the humor it churns out is notoriously hit-or-miss.","chinese":"电视网似乎将其播出时间最长的喜剧节目视为神圣不可侵犯， 即使其制作的赐默内容素质参差不齐， 也依然将其保留在节目表中。"},"p02r10":{"english":"Despite the wealth & profusion of medical information available through e-mail, the Intemet and mobile devices, not many patients are taking advantage of the potential of electronic ‘communications for health-related needs.","chinese":"尽管通过电子邮件 、 互联网和移动设备可以获取大量医疗信息， 但很少有患者利用电子通信来满足健康相关需求。"},"p03r01":{"english":"The photocopier, widely adopted in the 1960s, became not merely a vehicle for copying but one for publishing in a clandestine & a surreptitious manner, so that ideas could be circulated without interference from potential censors.","chinese":"复印机在 20 世纪 60 年代被广泛采用， 不仅仅是复制的工具， 更成为以隐秘方式传播的出版工具， 使思想能够在不受潜在审查者干扰的情况下传播。"},"p03r02":{"english":"Meteorology is one of the few fields of applied science that demands prediction; since prediction involves considerable uncertainty and uncertainty is anathema to & repellent to_ scientists, meteorology will continue to exist in a fraught intellectual space.","chinese":"气象学是少数需要预测的应用科学领域之一; 由于预测涉及相当大的不确定性， 而不确定性令科学家厌恶， 气象学将继续存在于一个充满矛盾的知识领域中。"},"p03r03":{"english":"Cunliffe is intellectually indebted to the Annales school of French economic and social historians, which emphasized largely static environmental influences and long-term historical continuity and regarded political events mainly astrivial & ephemera.","chinese":"康利夫在思想上深受法国经济与社会史学派年鉴学派的影响， 该学派强调主要是静态的环境影响和长期的历史延续性， 并将政治事件视为琐碎和短暂。"},"p03r04":{"english":"Looking back on a project that they had approached with both greattrepidation & misgivings and considerable aspirations, they were amused to recognize that neither the fears nor the hopes had been at all realistic.","chinese":"实际。"},"p03r05":{"english":"Ina field of egotists, Bloomfield is unassuming & modest, often praising her competitors and punctuating her correspondence with self-deprecating remarks.","chinese":"在一群自负的人中， 布鲁姆菲尔德廊逊， 总是赞扬她的竞争对手， 并在通信中时常带有自嘲的言辞。"},"p03r06":{"english":"Aerial viewings of the gigantic stone horse attributed to the Native American Quechuan people fail to reveal & manifest the considerable artistry required to create the piece: the horse appears crudely constructed unless carefully examined from the ground.","chinese":"从空中观看这匹被认为是美洲原住民克丘亚人创作的巨型石马， 无法展现其创作所需的精湛技艺; 除非从地面仔细观察， 否则这匹马看起来像是粗制滥造的。"},"p03r07":{"english":"Itis true that science, and more particularly scientists, cede & relinquish cherished paradigms with great reluctance and that when they do, scientific revolutions may result.","chinese":"确实， 科学， 尤其是科学家， 总是极不情愿地放弃珍视的范式， 而当他们这样做时， 可能会引发科学革"},"p03r08":{"english":"The tribes’ proclivity toward & predilection for a settled mode of living was derived from their long-standing traditions, which, though differing from one tribal group to another, always included a resistance to nomadic lifestyles.","chinese":"部落对定居生活方式的倾向源于其长期的传统， 这些传统虽然因部落群体不同而有所差异， 但始终包含对游牧生活方式的抵制。"},"p03r09":{"english":"Although traditionally artists have rightly been seen as the most perceptive & discerning audience for the work of their colleagues, today taste is also created by critics and curators and occasionally by collectors.","chinese":"尽管传统上艺术家被公认为对同行作品最敏锐的观众， 但如今品味也由评论家和策展人创造， 有时还包括收藏家。"},"p03r10":{"english":"If itis wrong to justify human selfishness on the basis of the alleged selfishness of nature, then it is equally mistaken to espouse altruism & benevolence merely because some animals happily assist each other.","chinese":"如果以所谓的自然自私性为依据来为人类的自私辩护是错误的， 那么仅仅因为某些动物乐于互相帮助而提倡利他主义也同样是错误的。"},"p04r01":{"english":"Computational psychologists, since they take the operation of a computer as a model, appropriate & borrow concepts from computer science to explain what the mind is and how it works.","chinese":"计算心理学家以计算机的运作为模型，_ 借用计算机科学的概念来解释心智的本质及其运作方式。"},"p04r02":{"english":"Flawed as it may be because it is conducted by subjective scientists, science itself has methods that help us bypass & circumvent our biases and talk about objective reality with some validity.","chinese":"尽管科学可能因主观的科学家而存在缺陷， 但科学本身的方法能够帮助我们规避偏见， 并以一定的有效性讨论客观现实。"},"p04r03":{"english":"Typefaces, in one sense, are just like styles of shoes: they proliferate & abound because different people have different tastes and identities and because both creators and users value novelty for its own sake.","chinese":"字体在某种意义上就像鞋子的款式: 它们之所以层出不穷， 是因为不同的人有不同的品味和身份认同， 同时创作者和使用者都珍视新颍性本身。"},"p04r04":{"english":"‘As a way of checking & stemming the negative impacts of overdependence on a single export product—crude oil, the Nigerian government passed legislation in 1999 intended to revitalize the moribund solid minerals sector.","chinese":"作为检查并坎制过度依赖单一出口产品 -一原油一- 所带来的负面影响的一种方式， 尼日利亚政府于 1999 年"},"p04r05":{"english":"Although in the mid-1970s nuclear power seemed poised for a still greater role in energy supply, in fact the waning & ebbing of its prestige had already begun.","chinese":"尽管在 20 世纪 70 年代中期， 核能似乎准备在能源供应中扮演更重要的角色， 但事实上， 其声望的衰退早已开始。"},"p04r06":{"english":"Established scientists recognize that peer review of manuscripts submitted to scientific journals is critical to science, but this recognition engenders & induces a certain ambivalence in them, since reviewing takes time away from their research.","chinese":"资深科学家认识到， 对提交至科学期刊的手稿进行同行评审对科学至关重要， 但这种认识也引发了他们一定的矛盾心理， 因为评审会占用他们的研究时间。"},"p04r07":{"english":"The adipose tissue in which our bodies store fat from the food we eat has traditionally been thought of as inert & passive, but in reality this tissue constitutes a dynamic organ, not a mere repository.","chinese":"我们身体储存食物脂肪的脂肪组织传统上被认为是惰性且被动的， 但实际上， 这种组织是一个动态器官， 而非单纯的储存库。"},"p04r08":{"english":"‘Some consider the theorem Emmy Noether first published in 1918 to be as important as Einstein's theory of relativity, since much of today's vanguard research in physics is undergirded by & dependent on_ Noethers theorem.","chinese":"一些人认为艾米 ' 诺特在 1918 年首次发表的定理与爱因斯坦的相对论一样重要， 因为当今许多前沿的物理研究都基于诺特定理。"},"p04r09":{"english":"Whether the film is a rigorous & a faithful adaptation of the legend is debatable: the author of the screenplay claims that it was based on the original tale, but admits taking some interpretive license with the story.","chinese":"CPRVSHSM SH ESLMAAAAM: 剧本作者声称其基于原始故事， 但也承认对情节进行了某些解读性的改动。"},"p04r10":{"english":"Evidence of the human brain's flexibility & malleability abounds: violinists, for example, tend to have larger cortical areas devoted to processing signals from their fingering hands than do non- violinists","chinese":"人类大脑具有灵活性和可塑性的证据比比此是: 例如， 小提琴手遂常比非小提琴手拥有更大的皮层区域来处理来自运指手的信号。"},"p05r01":{"english":"The scholars’ hypothesis challenges the scope of human psychological and behavioral universals, but does not dispense with them entirely: the team remains confident that displays of pride, for instance, are ubiquitous & omnipresent_.","chinese":"学者们的假设挑战了人类心理和行为普遍性的范围， 但并未完全否定它们: 例如， 团队仍然确信， 骄傲的表现是无处不在的。"},"p05r02":{"english":"In Ramachandran’s opinion, itis perfectly acceptable to propose bold speculations about the brain, even if these speculations seem unfounded & baseless; as Ramachandran frequently remarks, science thrives on risky conjecture.","chinese":"EMSRS BR, HUATARMPARHIERS TD LUSSH, RHE NIEMRIME; 正如拉马"},"p05r03":{"english":"While normal floods resulting from usual monsoon rainfall are essential for & indispensable to the growth of crops, recently there has been an increase in the frequency of high-intensity floods that do not have such welcome effects.","chinese":"虽然由常规季风降雨引发的正常洪水对作物的生长是必需的， 但最近高强度洪水的频率有所增加， 这种洪水并没有如此受欢迎的效果。"},"p05r04":{"english":"In establishing that the dust she had observed constitutes two percent of the mass in the quadrant, the astronomer showed that the dusts extreme visual prominence belies & masks its relatively minor contribution to the total mass of the region.","chinese":"在确定她观察到的尘埃占该象限质量的 2% 时， 这位天文学家表明， 人尘埃的极高视觉显著性掩盖了其对该区域总质量的相对微小贡献。"},"p05r05":{"english":"For literary critics and book reviewers, the notion of critical authority has become fluid & unstablein an age of quick, teeming Internet response, where all the old critical standards and parameters are in the process of being reinvented.","chinese":"对于文学评论家和书评人来说， 在快速且充满活力的互联网回应时代， 批评权威的概念已变得不稳定且难以捉摸， 所有人旧有的批评标准和参数都在被重新定义的过程中。"},"p05r06":{"english":"The idea that Jim was truculent & pugnacious, that he loved fighting for the sake of fighting, was a mistake, in reality he was a kind and gentle person.","chinese":"认为吉姆是好斗的， 喜欢为战斗而战斗的想法是错误的， 实际上他是一个善良而温和的人。"},"p05r07":{"english":"French's tone was reasonable, deferential & respectful almost, but the gaze she fixed on Backhouse over her reading spectacles had something of defiance in it.","chinese":"French 的语气相当合理， 几乎 4, (ohana 读眼久注视 Bs 语几乎是 _ 恭敬而苯重 _ 的， 但她透过阅读眼镜注视 Backhouse 的目光中带着几分"},"p05r08":{"english":"Another challenge to biologists and land-use planners alike is that while human-induced changes to the landscape are somethings imperceptible & indiscernible, they can nevertheless drastically alter the habitat for some plants and animals.","chinese":"另一个对生物学家和土地使用规划者的挑战是， 尽管人类引起的景观变化有时 _ 难以察党 _， 但它们仍然可能极大地改变某些植物和动物的栖息地。"},"p05r09":{"english":"The sound of disembodied human breathing in Miyazaki's films is at once a presence, close to the listener's ear, and a ghostly absence due to its lack of a visual counterpart & correlative.","chinese":"宫崎骏电影中无形的人类呼吸声既是一种贴近听者耳边的存在， 又因缺乏视党对应而显得幽灵般虚无。"},"p05r10":{"english":"The rebellion was a cerebral & a dispassionate_one, driven less by ardor than by reason and calculation.","chinese":"这场叛乱是理性且冷静的， 更少由激情驱动， 而更多依靠理智和算计。"},"p06r01":{"english":"In literature, thrillers thrive on heroes and villains, and usually the characterization is not very nuanced & subtle_; writers don't want to confuse or slow the plot.","chinese":"在文学作品中， 惊悚小说依赖于英雄和反派， 角色通常不会非常细脖; 作家不希望让情节变得混乱或拖慢进展。"},"p06r02":{"english":"That the announcement of the new treatment was greeted with euphoria & jubilation__is hardly surprising given the claims made for it, but attitudes were markedly tempered once the paucity of supporting data became apparent.","chinese":"新疗法的宣布引发了狂喜， 这并不令人意外， 考虑到对其效果的宣传， 但一旦支持数据的匮乏显现出来， 态度便明显冷却了下来。"},"p06r03":{"english":"Although traditionally artists have rightly been seen as the most insightful & discriminating audience for the work of their colleagues, today taste is also created by critics and curators and occasionally by collectors.","chinese":"尽管传统上艺术家被公认为对其同行作品最具洞察力和鉴赏力的观众， 但如今品味也由评论家和策展人创造， 有时还包括收藏家。"},"p06r04":{"english":"One of the incongruities of modem industry, according to Reck and Graedel, is that we manufacture modern products with the most sophisticated technologies available yet generally adopt relatively basic & crude approaches to recycling them.","chinese":"根据 Reck 和 Graedel 的说法， 现代工业的一个矛盾之处在于， 我们用最先进的技术制造现代产品， 但在回收这些产品时通常采用相对原始粗糙的方法。"},"p06r05":{"english":"Scholars of the civil rights movement have often characterized it as springing from social, political, and economic structures unique to & characteristic of the South, thus overlooking the tradition of civil rights activism in other regions of the country.","chinese":"民权运动的学者常将其描述为源于南方独特且典型的社会 、 政治和经济结构， 从而忽视了其他地区民权运动传统的存在。"},"p06r06":{"english":"While there is no evidence that Bigfoot is real, several well-known species were once thought to befabulous & legendary; the okapi, for instance, was known as the “African unicorn’ until explorers obtained proof of its existence.","chinese":"尽管没有证据表明大脚怪是真实存在的， 但一些著名的物种曾被认为是神话传说的; 例如， 堆加皮曾被称为 \"非洲独角兽 *“， 直到探险者获得了其存在的证据。"},"p06r07":{"english":"Inits few decades of existence, the field of technology assessment has undergone large changes: its original high ambitions to predict consequences of technology have been tempered & modulated if not discarded.","chinese":"在短短几十年的发展中， 技术评估领域经历了巨大变化: 最初预测技术后果的高远抱负已被调整甚至放"},"p06r08":{"english":"Harper Lee's narration in To Kill a Mockingbird is a hodgepodge & a patchwork, mixing an adult's and a child's perspective according to no logic other than the immediate exigencies of the plot.","chinese":"哈珀: 李在 《 杀死一只知更鸟 》 中的叙述是一个大杂烩， 混合了成人和儿童的视角， 仅根据情节的即时需要而非逻辑进行切换。"},"p06r09":{"english":"Although streams of solar particles cause beautiful auroras-the northern and southern lights— sometimes their consequences are less benign & innocuous: their electromagnetic effects, for instance, can overload power grids and damage orbiting satellites.","chinese":"尽管太阳粒子流会产生美丽的极光一一北极光和南极光一一但有时它们的后果却不那么良性: 例如， 它们的电磁效应可能会使电网过载并损坏轨道卫星。"},"p06r10":{"english":"Well organized and researched and including all significant discoveries and medical scientists, this history of Western medicine has justly been called encyclopedic & exhaustive_.","chinese":"内容详尽且结构严谤， 涵盖所有重要发现和医学科学家， 这部西方医学史被公认为百科全书式的全面著"},"p07r01":{"english":"A.cure for the common cold has been so elusive that it has become a modern symbol of futility & pointlessness.","chinese":"治就普通感慎一直难以实现， 已成为现代象征的徒劳无功。"},"p07r02":{"english":"There is frequently a protracted time interval between the introduction of an innovative musical composition and its public acceptance; the concert-going public often spurns the novel & original in favor of the familiar for a prolonged period.","chinese":"创新的音乐作品从问世到被公众接受之间往往存在较长的时间间隔; 听众通常会在较长时间内拒绝新颖独特的作品， 而偏爱熟悉的作品。"},"p07r03":{"english":"For decades, Pluto seemed to be the mysteriously dwindling & contracting planet: it was first thought to be about as large as Earth, but, subsequently, measurements had it smaller and smaller.","chinese":"几十年来， 冥王星似乎是一个神秘的逐渐缩小的星球: 起初人们认为它和地球差不多大， 但后来测量显示"},"p07r04":{"english":"The sailors realized too late that winds had shifted the ice in such a way as to obstruct the ship's path; this process had been so gradual & imperceptible that it was completed by the time they discovered the effect.","chinese":"水手们发现得太晚了， 风已经将冰块移动到阻碍船只航行的方式; 这一过程是如此渐进且难以察觉， 以至于当他们发现结果时， 已经完成了。"},"p07r05":{"english":"In the nineteenth century, the circus, for all its glitz and even its glamour, was entertainment with an old soul, a respite from & a break from the fast-forward pace of change in modem life.","chinese":"在十九世纪， 马戏团尽管充满光彩甚至魅力， 却是一种带有古老灵魂的娱乐， 现代生活快节奏变化中的喘"},"p07r06":{"english":"Sokari Douglas Camp was neglected & forsaken in the early 1990s by many of London's commercially driven art dealers and galleries, some of whom apparently found her themes difficult to market.","chinese":"中一些人显然认为她的主题难以推广。"},"p07r07":{"english":"The concept of increasing complexity of organisms has a contentious & a fraught history among evolutionary biologists, and yet many laypeople would unhesitatingly say that the pattern applies to the history of life on Earth","chinese":"生物体复杂性增加的概念在进化生物学家中一直存在争议且充满挑战的历史， 然而许多普通人会毫不犹驻地认为这一模式适用于地球生命的历史。"},"p07r08":{"english":"Despite the general bias & orientation of Roman archaeological studies toward the major cities and their monuments, archaeology has contributed much to a better understanding of rural developments in Roman territory.","chinese":"尽管罗马考古研究通常偏向于主要城市及其纪念碑， 考古学对罗马领土农村发展的理解贡献良多。"},"p07r09":{"english":"Our mass media are much more fascinated by bad ideas or the failure of good ones than by successes: we drown in bad news—tales of how things went wrong 一 but we have only the most cursory & perfunctory discussion on how they might go right.","chinese":"FEI A AR A YA IA TASTE AI RGR, MME: 我们被坏消息淹没一一关于事情如何出错的故事一一但对于事情如何可能变好， 我们只有最粗路的讨论。"},"p07r10":{"english":"Because archaeology explores the most profound changes in human history by means of a grossly incomplete record; it has invited the sort of bold, imaginative interpretation in which speculation too easily becomes untethered from & divorced from evidence.","chinese":"由于考古学通过极其不完整的记录探索人类历史中最深刻的变化， 它吸引了那种大胆而富有想象力的解读， 其中推测很容易脱离证据。"},"p08r01":{"english":"For certain economists, “pure” economic theory, that is, economic theory abstracted from & divorced from a specific social structure, is impossible, much like a concept of anatomy that investigates no specific species.","chinese":"对于某些经济学家来说，\" 纯粹 \"的经济理论， 即从特定社会结构中抽象并脱离的经济理论， 是不可能的， 就像一种不研究具体物种的解剖学概念一祥。"},"p08r02":{"english":"Contrary to popular myth, cockroaches are not especially tough or radiation resistant; indeed, they are pretty average & undistinguished as insects go.","chinese":"与普遍的误解相反， 里螂并不特别坚韧或抗辐射; 事实上， 作为昆虫来说， 它们相当普通。"},"p08r03":{"english":"Although the virtues of supplementing wild fish populations with fish from hatcheries are often extolled & acclaimed__, scientific studies have indicated that fish stocking can harm the wild, native species of the water body.","chinese":"地物种造成危害。"},"p08r04":{"english":"While the rate at which absolute global sea level is rising may seem imperceptible & trivial__ it has been far from an incidental factor in human history.","chinese":"虽然全球海平面上升的速度看似微不足道， 但它在人类历史中绝非无关紧要的因素。"},"p08r05":{"english":"The bird-watchers’ ineptitude at & maladroitness in distinguishing personal interpretations from factual observations was a liability in their stated goal of obtaining objective information about the everyday behavior of ravens.","chinese":"鸟类观察者在区分个人解读与事实观察方面的笨拙是他们实现获取乌鸦日常行为客观信息这一目标的障"},"p08r06":{"english":"The reliable production of usable energy through the controlled fusion of hydrogen atoms into helium remains an elusive dream: even the most ardent efforts to achieve it have thus far been thwarted & frustrated_.","chinese":"BMCARFT BRS MARE Shs RAS MESA: 即使是最热切的努力迄今也已被控败。"},"p08r07":{"english":"Even though Our Lady of the Forest achieves clinical evenhandedness in depicting the most depressing members of a small logging town, the novel lacks a single likable character and too often runs aground on stilted & wooden_ writing","chinese":"人喜爱的角色， 并且经常因生硬的写作而陷入困境。"},"p08r08":{"english":"The tools of science are so specialized that we accept them as a kind of occult & arcane_ machinery for producing knowledge: we know that they work, but cannot explain why.","chinese":"科学工具如此专业化， 以至于我们将其视为一种神秘机械， 用于生产知识: 我们知道它有效， 但无法解释原因。"},"p08r09":{"english":"The painter Fu Baoshi lived and worked through a tumultuous period in Chinese history, buoyed & sustained by exceptional talent and a steely dedication to his art.","chinese":"画家全抱石在中国历史的动荡时期生活和创作， 和凭借非凡的才华与对艺术的坚定执着得以支撑。"},"p08r10":{"english":"Whereas the original editor had sacrificed clarity for brevity and her successor had been too prolix & verbose_, the new editor took an intermediate approach, explicit as to the purport of each document and not too ambitious in detail.","chinese":"原来的编辑为了简洁牺牲了清晰度， 而她的继任者则过于宛长， 新编辑采取了中间的方式， 对每份文件的意图表达明确， 同时不过分追求细节。"},"p09r01":{"english":"Stannard may be hoping to resurrect Spark's literary reputation with this book, given its unstinting & generous praise for her creative talents.","chinese":"斯坦纳德可能希望通过这本书重塑斯帕克的文学声誉， 因为它对她的创作才华给予了豪无保留的赞美。"},"p09r02":{"english":"Early natural history collections in eighteenth-century Europe were fundamentally miscellaneous & thoroughly eclectic: a bear's tooth might sit incongruously alongside a piece of silverwork or, in the menagerie, a South American capybara might be housed next to an African baboon.","chinese":"18 世纪欧洲的早期自然历史收藏品本质上是杂乱无章且极其多样化的; 一颗能牙可能与一件银器不协调地摆放在一起， 或者在动物园蜂， 一只南美水豚可能被安置在非洲狂卯旁边。"},"p09r03":{"english":"In this otherwise thorough & exhaustive study, the internal tensions resulting from the increasing integration of the United States with the world economy are simply mentioned rather than analyzed.","chinese":"在这项本应详尽的研究中， 美国与全球经济日益融合所产生的内部紧张关系仅被提及， 而未进行分析。"},"p09r04":{"english":"Because the political situation seriously impeded international communication, French scientific research was at that time uncharacteristicallyinsular & parochial","chinese":"由于政治局势严重阻碍了国际交流， 法国的科学研究在当时表现得异常封闭。"},"p09r05":{"english":"My colleagues disparaged & dismissed the journalist’ s vaunted expertise at securing high-profile interviews, declaring that, given her family’ s connections to celebrities, obtaining such interviews must be no more difficult than asking a friend out for coffee.","chinese":"我的同事贬低并否定了这位记者在获取高端采访方面备受推崇的专业能力， 声称鉴于她家族与名人的关系， 获得这样的采访不过像约朋友虽咖啡一样简单。"},"p09r06":{"english":"The paucity & dearth_of criteria for determining what is meant by balance and whether itis beneficial makes it difficult to evaluate claims that probiotics promote a healthy balance of microorganisms in the body.","chinese":"缺乏判断 \"平衡 ”含义及其是否有益的标准， 使得难以评估益生菌促进体内微生物健康平衡的相关说法。"},"p09r07":{"english":"Bolstering & Buttressing_the idea that attention is a limited resource, scientists have repeatedly observed that drivers using mobile phones are slower to react and more apt to miss important details than are drivers focused solely on road.","chinese":"强化注意力是有限资源这一观点， 科学家多次观察到， 使用手机的司机反应更慢， 更容易忽略重要细节， 而专注于道路的司机则表现更好。"},"p09r08":{"english":"After rising continuously over the summer, commodity prices fell, leaving analyst wondering whether the downward trend is a turning point or merely a lull & respite before demand picks up in the winter months.","chinese":"在整个夏季持续上涨后， 商品价格下跌， 让分析师们思考这一下降趋势究竟是一个转折点， 还是在冬季需求回升前的短暂平静。"},"p09r09":{"english":"One of the peculiarities of humans is that we irrationally gravitate to the predictable and avoid risk, whatever the reasons for this predilection & proclivity, it is hardly a sound basis for dealing with complex, long-term problems.","chinese":"人类的一个特殊之处在于， 我们非理性地倾向于可预测性并避免风险， 无论这种偏好是什么原因， 这都难以成为应对复杂且长期问题的可靠基础。"},"p09r10":{"english":"Historically, the depletion of soils nitrogen has been one of the most stubborn & intractable problems faced by farmers: an essential nutrient, nitrogen is quickly leached from soil, and farmers have struggled to find ways to replenish it.","chinese":"历史上， 土壤中氨的耗竭一直是农民面临的最顽固难解的问题之一: fFA-MMSMAD, ARRAKL 二中流失， 农民一直在努力寻找补充氨的方法。"},"p10r01":{"english":"Titan, Saturn's largest moon, looks surprisingly familiar & recognizable, even though it is a cold, dimly lit world made from unknown materials.","chinese":""},"p10r02":{"english":"Joshua Gisemba Bagaka found that the pedagogical results of group projects and other engaged learning activities in Kenyan mathematics classroom were mixed & inconsistent; such activities, then, may not be the best way of improving mathematics education.","chinese":"约书亚吉森巴. 巴加卡发现， 在肯尼亚数学课堂中， 小组项目和其他参与式学习活动的教学效果表现为参差不齐， 因此， 这些活动可能并不是改善数学教育的最佳方式。"},"p10r03":{"english":"In noting that critical and popular opinions about Lis art coincided, Chuang conceded & acknowledged the existence of an exception to her general theory of art criticism, which posits that critics’ views do not intersect with those of the general public.","chinese":"在指出对这的艺术的批评和大众意见一致时， 庄承认了她关于艺术批评的一般理论存在一个例外， 该理论认为评论家的观点与大众的看法并不交集。"},"p10r04":{"english":"Coagulation factors are useful proteins whose simple names—many are known only by Roman numerals—belie & mask their importance and the specificity of their roles in the thinning and clotting of blood.","chinese":"凝血因子是有用的蛋白质， 其简单的名称一一许多仅以罗马数字为人所知一一掩盖了它们在血液稀释和凝固中的重要性和特定作用。"},"p10r05":{"english":"There is a revelation on almost every page of this book, and the author's prose is awkward & ungainly in the best possible way: blunt, sweet, off-kilter, and often quite funny.","chinese":"这本书的每一页几乎都有一个启示， 作者的文笔以最好的方式展现出一种笨拙但别具一格的风格: 直率 、 温暖 、 古怪且常常非常有趣。"},"p10r06":{"english":"For parents, the pleasure of letting children choose which book to read aloud together is not always unalloyed & unqualified: | well remembered my inner groans when my child would constantly pick my least favorite book from the shelf.","chinese":"对于父母来说， 让孩子选择一起朗读的书籍的乐趣并不总是纯粹的: 我清楚记得， 当我的孩子总是从书架上挑选我最不喜欢的书时， 我内心的嘉叹。"},"p10r07":{"english":"Baker was struck by the amount of discordance & contention she saw at the renowned medical facility; for all their experience, the physicians could not seem to agree on the correct diagnosis for any given patient.","chinese":"贝克对这家著名医疗机构中所见的分歧感到震惊; 尽管医生们经验丰富， 但他们似乎无法就任何患者的正确诊断达成一致。"},"p10r08":{"english":"Recent research runs counter to the long-cherished notion that a small drop in body temperature during and after surgery is either immaterial & inconsequential or actually protects the patient by slowing metabolism and reducing the body's demand for blood and oxygen.","chinese":"最近的研究与长期以来的观念相悖， 即在手术期间和之后体温略微下降要么无关紧要， 要么实际上通过减缓新陈代谢并降低身体对血液和和氧气的需求来保护患者。"},"p10r09":{"english":"In Schaller's contradictory introduction to the book, she alternately applauds and denounces & lambasts humankind’s role in animal conservation.","chinese":"在沙勒矛盾的书序中， 她时而赞扬， 时而谴责人类在动物保护中的角色。"},"p10r10":{"english":"A few decades ago the idea of animal morality would have been met with derision & ridicule; however, recent research suggests that animals not only act altruistically but also have the capacity for empathy, forgiveness, trust, and reciprocity.","chinese":"+E, DWBEMRSABAMR, 然而， 最近的研究表明， 动物不仅会表现出利他行为， 还具备同理心 、 宽恕 、 信任和互惠的能力。"},"p11r01":{"english":"Berwick, middle-aged, soft-spoken, and unprepossessing & unremarkable, with a keen sense of how to use this apparent ordinariness to his advantage, began with a gripping story about how a firefighter saved himself during a forest fire by using a completely improbable tactic.","chinese":"一个引人入胜的故事开场， 讲述了一名消防员在森林火灾中用一种完全出人意料的策略拯救自己的经历。"},"p11r02":{"english":"The environmental threat posed by the New Zealand mud snail, an invasive species, is exacerbated & aggravated by the snail's small size, which facilitates its spread across watersheds through human activity.","chinese":"新西兰泥螺这种入侵物种带来的环境威胁因其体型小巧而被加剧， 这种特性通过人类活动促进了其在流域间的传播。"},"p11r03":{"english":"As astronomers do not yet have a good understanding of the fundamental nature of dark matter, it should not be a surprise that astronomy students’ ideas about dark matter are, at best, superficial & sketchy.","chinese":"由于天文学家尚未很好地理解暗物质的基本性质， 天文学学生对隙物质的看法充其虽也只是肤浅。"},"p11r04":{"english":"Though Fine leavens her work with humor and playfulness, she can be an acerbic & a harsh writer, mincing no words in her judgements of other scientists’ work.","chinese":"尽管法恩在作品中融入了幽默和趣味， 但她也可以是一个尖刻严厉的作家， 对其他科学家的作品评判毫不留情。"},"p11r05":{"english":"In the Old Southwest, only writers who showed exceptional determination & resolve were likely to become widely known, because the region's weak infrastructure inhibited the development of publishing beyond local newspapers that served small towns.","chinese":"在旧西南地区， 只有表现出非凡决心的作家才有可能广为人知， 因为该地区薄弱的基础设施阻碍了出版业的发展， 出版物仅限于服务小城镇的地方报纸。"},"p11r06":{"english":"The splendor & brilliance of native South American textiles at the time of the Spanish conquest should not be surprising: it represented the apogee of one of the world's oldest and most sophisticated weaving and dyeing traditions.","chinese":"南美洲原住民纺织品在西班牙征服时期的辉煌与卓越并不令人惊讶: 它代表了世界上最古老且最复杂的织造和染色传统的疾风。"},"p11r07":{"english":"Meteorology is one of the few fields of applied science that demands prediction, since prediction involves considerable uncertainty and uncertainty is anathema to & repellent to_ scientists, meteorology will continue to exist in a fraught intellectual space.","chinese":"气象学是少数需要预测的应用科学领域之一， 由于预测涉及相当大的不确定性， 而不确定性令科学家厌恶， 气象学将继续存在于一个充满矛盾的知识领域中。"},"p11r08":{"english":"Khirigsuurs, distinctive stone mounded monuments, are so ubiquitous & prevalent in central and western Mongolia that it has been argued that they were the defining features of the human landscapes of prehistoric Inner Asia.","chinese":"兰里苏尔， 这些独特的石堆纪念碑在蒙古中部和西部是如此普遍， 以至于有人认为它们是史前内亚人类景观的标志性特征。"},"p11r09":{"english":"The folktale is perhaps the most democratic & egalitarian_form of literature: a story that everyone is free to tell and embellish because it belongs to no one in particular.","chinese":"民间故事或许是最民主平等的文学形式: 一个人人都可以讲述和润色的故事， 因为它不层于任何特定的"},"p11r10":{"english":"Scientists are finding that the adult brain is for more malleable & plastic_ than they once thought: ‘our behavior and environment can cause substantial rewiring of the brain or a reorganization of its functions and where they are located.","chinese":"科学家们发现成年人的大脑比他们曾经认为的更加可塑: 我们的行为和环境可以导致大脑进行大晤度的重塑或功能及其位置的重新组织。"},"p12r01":{"english":"When Kim Dae Jung was decisively elected South Korea's president in December 1997, he was considered something of maverick & nonconformist but nevertheless the right man for the time and the job.","chinese":"当金大中在 1997 年 12 月果断当选韩国总统时， 他被认为是一个特立独行但仍然是那个时代和职位的合适人"},"p12r02":{"english":"Motorcycle riders in London have discovered an ingenious, albeit unscrupulous & dishonest, way of parking illegally without getting a ticket.","chinese":"伦敦的摩托车骑手发现了一种巧妙但不道德的非法停车方式， 可以避免被罚单。"},"p12r03":{"english":"The author argued that a relentless focus on political scandal was making it hard for even the least cynical & jaded politicians to maintain their faith in the nobility of public service.","chinese":"作者认为， 对政治丑闻的不懈关注使即使是最不愤世嫉俗的政治家也难以保持对公共服务高尚性的信念。"},"p12r04":{"english":"For everysympathetic & well-disposedreader of Vestiges there were many more who became vocal critics, and the book aroused heated opposition from a broad range of British society.","chinese":"对于每一位同情有友善的 《痕迹 》 读者， 都有更多人成为直言不讳的批评者， 这本书在英国社会的广泛范国内引发了激烈的反对。"},"p12r05":{"english":"By 1600, France's sense of itself as a nation bound by a shared destiny wasprecarious & uncertain, but over the course of the seventeenth century French culture regained the strength it had had in the Middle Ages.","chinese":"到 1600 年， 法国对自身作为一个由共同命运联系的国家的认知是脆弱且不确定的， 但在整个 17 世纪， 法国文化重新获得了中世纪时期的强盛。"},"p12r06":{"english":"For centuries people used the vocabulary of medicine to think about how our bodies are structured, but the language of distinct organs and systems does not do justice to the interwoven & integrated_nature of the body.","chinese":"几个世纪以来， 人们用医学的词汇来思考我们身体的结构， 但独立器宫和系统的语言无法充分体现身体的交织与整合本质。"},"p12r07":{"english":"The climate researchers’ prejudicial & tendentious_ method of presentation caused a stir among those who felt that scientific papers should be dispassionate in their delivery of evidence.","chinese":""},"p12r08":{"english":"The concept of the Hellenistic period in ancient history has proved useful but also slippery & elusive, with scholars disagreeing on the dates when the period began and ended.","chinese":"古代历史中的希腊化时期这一概念被证明既有用又难以捉措， 学者们对这一时期的起始和结束日期存在分"},"p12r09":{"english":"Excessive focus on what might have been can cause in us feelings of restlessness and regret, but some scientists are beginning to think that fancying an alternative reality might have restorative & tonic effects as well.","chinese":"过度关注可能发生的事情会让我们感到不安和后悔， 但一些科学家开始认为， 想象另一种现实可能也具有恢复和振奋的效果。"},"p12r10":{"english":"Robert McCance and Elsie Widdowson's The Chemica! Composition of Foods, published in 1940, contained an extraordinary fifteen thousand entries, making it the first collection of nutritional information for cooked and raw foods that could be consideredexhaustive & comprehensive_.","chinese":"罗伯特 ` 麦坎斯和埃尔西 ' 威多森于 1940 年出版的 《食品的化学成分 》 包含了惊人的一万五二条记录， 使其成为第一部可以被认为是详尽全面的熟食和生食营养信息合集。"},"p13r01":{"english":"Changes made to ecosystem in order to achieve a goal, such as food production or flood control, often yield & engender significant unforeseen trade-offs between other important products and service the ecosystems provide.","chinese":"为了实现某个目标 (如粮食生产或防洪 ) 而对生态系统进行的改变， 往往会产生重大且意想不到的权衡， 影响生态系统提供的其他重要产品和服务。"},"p13r02":{"english":"Although scientific progress leads to constant revision of ideas, one observation that has. remained robust & strong over the years is that there are a lot of insects in the world: some 950,000 species have been identified.","chinese":"尽管科学进步不断修正观念， 但多年来一个始终稳固的观察是， 世界上有大量的昆虫: 已识别的种类约有 95 万种。"},"p13r03":{"english":"At first, most of the famous fairy tales seem so implausible and so irrelevant to contemporary life that their persistence & survival is hard to understand.","chinese":"起初， 大多数著名的童话故事看起来既不可信和又与当代生活毫无关联， 因此它们的存续难以理解。"},"p13r04":{"english":"While it is always clear that the author's message is heartfelt, it is mostly buried by shortcomings of style, organization, and production, although the book does become more intelligible & readable toward the end.","chinese":"虽然作者的情感表达始终真执， 但由于风格 、 结构和制作上的不足， 这种情感大多被掩盖了， 不过这本书在结屁部分变得更加清晰易读。"},"p13r05":{"english":"Few ideas are more abused & misused than the notion that cultures evolve in Darwin fashion; many academics have begun writing about cultural evolution, but few treat the underlying Darwinian logic with the care it deserves.","chinese":"没有什么概念比文化以达尔文方式进化的观点更被滥用与误解; 许多学者开始撰写关于文化进化的内容， 但很少有人以应有的谨慎对待其背后的达尔文逻辑。"},"p13r06":{"english":"Although Wynne claims to recognize that insufficient & meager evidence is available to make definitive statement, she offers them nonetheless, arriving at some sweeping generalizations.","chinese":"尽管温恩声称意识到现有证据 _ 不足且贫乏 _“， 无法做出明确的陈述， 但她仍然提出这些观点， 并得出一些过于笼统的结论。"},"p13r07":{"english":"The media have constantly disparaged the governor's competence and have found a public only too eager to applaud their mockery & derision.","chinese":"媒体不断贬低州长的能力， 而公众也乐于赞同他们的嘲讽。"},"p13r08":{"english":"In order to cultivate new repertoire, the music industry is providing a hearing for previously anonymous & obscure composers.","chinese":"为了培养新的曲目， 音乐行业正在为此前默默无闻的作曲家提供展示机会。"},"p13r09":{"english":"Communicating articulately is typically regarded as an aggressive, persuasive talent, but it can also be protective: it allows a certain feigned & false & false closeness, conveying proximity while actually maintaining distance.","chinese":"清晰表达通常被认为是一种具有攻击性和说服力的才能， 但它也可以具有保护性: 它允许一种虚假的亲近三， 传递出接近的错觉， 同时实际上保持距离。"},"p13r10":{"english":"The Chavez Pass archaeological site was initially interpreted as indicative of a hierarchical & a stratified society, since it was thought to have been at the center of a cluster of smaller, contemporary settlements that it presumably controlled.","chinese":"查韦斯山口考古遗址最初被解读为表明一个等级分明的社会， 因为它被认为位于一群较小的同时期聚落的中心， 并可能对其进行控制。"},"p14r01":{"english":"As a historical genre, biography is best when meticulous & thorough, a careful reconstruction of the past in all its unfamiliar particularity.","chinese":"作为一种历史体哉， 传记在 、 细致入微 、 时最为出色， 能够细心重现过去所有不熟悉的细节。"},"p14r02":{"english":"The ambassador's critical remarks seemed to be less a product of purposefulness & design and more the careless utterances of a fatigued or undisciplined individual.","chinese":"大使的批评言论似乎与其说是出于故意， 不如说更像是疲惫或缺乏自律的人随意的言辞。"},"p14r03":{"english":"Although the courts have underwritten & endorsed an extremely flexible test for determining the admissibility of expert testimony, that does not mean that all experts will be allowed to testify.","chinese":"尽管法院已经支持并认可了一种极为灵活的测试方法来确定专家证词的可采性， 但这并不意味着所有专家都可以作证。"},"p14r04":{"english":"As the biography makes plain, the scientist led an itinerant & a peripatetic sort of life, rarely remaining in one place for long,","chinese":"正如传记所述， 这位科学家过着漂泊的生活， 很少长时间待在一个地方。"},"p14r05":{"english":"British critics covering African American musicians performing in London in the 1910s had little idea how to distinguish what was authentic African American music from what was spurious & specious, but they knew such a distinction existed.","chinese":"20 世纪 10 年代， 报道非裔美国音乐家在伦敦演出的英国评论家几乎无法分辩什么是真正的非毅美国音乐， 什么是虚假， 但他们知道这种区别是存在的。"},"p14r06":{"english":"Its a sign of John Dramani Mahama’s maturity as a writer that he is willing to consider his country's future so dispassionately & analytically: his memoir is appealingly honest, given to clear-eyed assessments rather than exaggerated accounts of achievements.","chinese":"这体现了约翰. 德拉马尼. 马哈马作为作家的成熟， 他愿意如此冷静且理性地思考自己国家的未来: 他的回包录坦率而吸引人， 更多是清醒的评估， 而非对成就的夸大描述。"},"p14r07":{"english":"The action in Zadie Smith's novel On Beauty is mediated by an unabashedly obtrusive & conspicuous narrator who does not hesitate to inform us, as once upon a time the narrators of novels were wont to do, how we behave in general and how society usually works","chinese":"小说中的叙述者常做的那样， 我们通常的行为方式以及社会的运作规律。"},"p14r08":{"english":"Although the claim that no one knows what dark matter is remains sound & unassailable, some scientists dispute the parallel assertion that dark matter has not been detected.","chinese":"尽管 \"没有人知道暗物质是什么 \"这一说法仍然无侈可击， 一些科学家对 “暗物质尚未被探测到 \"这一类似断言提出了质疑。"},"p14r09":{"english":"The recent exhibition on Dadaism is nothing if not timely & opportune, for the visual arts are currently awash in Dadaist gestures and gambits of one variety or another.","chinese":"最近关于达达主义的展览无疑是再合适不过的， 因为当下视觉艺术充满了各种形式的达达主义手法与策"},"p14r10":{"english":"A priori mathematics, according to Galileo, does not obviate & displace the need for observation, but mathematics does allow us to deduce unobservable properties and thus to penetrate further into the structure of nature than observation does.","chinese":"根据分利略的观点， 先验数学并不能取代观察的必要性， 但数学确实使我们能够推导出不可观察的层性， 从而比单纯观察更深入地了解自然的结构。"},"p15r01":{"english":"‘Some social insects, such as bees and ants, are celebrated for their industriousness and engineering feat, but popular culture has not generally applauded & extolled termites for theirs— even though they can build mounds twenty feet high.","chinese":"一些社会性昆虫， 比如蜜巍和蚂蚁， 以其勤劳和工程成就而闻名， 但大众文化通常并未赞扬白蚁的这些特质一一尽管它们能够建造高达二十英尺的土丘。"},"p15r02":{"english":"What they see in Jimenez is the one candidate capable of decisive leadership, in stark contrast to Diaz, whose team in office has been marred by irresolution & vacillation.","chinese":"他们眼中的希门尼斯是唯一能够果断领导的候选人， 这与迪亚兹形成鲜明对比， 后者的团队在任期间因优"},"p15r03":{"english":"What differentiates this book from more traditional works on grammar is that it reserves its scolding & admonishment not for students of writing, but for teachers who harbor unduly restrictive views.","chinese":"这本书不同于更传统的语法著作之处在于， 它将其批评与告诫的对象从写作的学生转向了持过于限制性观点的教师。"},"p15r04":{"english":"Given that the department director was such a feeble contributor, sitting silently at important policy meetings and usually deferring to low-level aides, it was surprising that he had such a reputation for perspicacity & discernment.","chinese":"鉴于部门主管在重要政策会议上表现得如此无所作为， 遂常沉默不语并依赖低级助手， 令人惊讶的是他竞然以敏锐著称。"},"p15r05":{"english":"Scenes of bustling streets full of well-dressed citizens going about their business contradict & gainsay the growing hardship faced by all but the richest local residents.","chinese":"街道上照晤接接的景象， 衣着光鲜的市民访于各自事务， 与除最富有的当地居民外所有人面临的日益严重的因境形成了鲜明对比。"},"p15r06":{"english":"There is very little inertia & stasis in culture: an art form or a practice (or a language or an institution) can become extinct in a generation if it does not evolve.","chinese":"文化中几乎没有 ”惯性与停湛 _: 一种艺术形式或实践 (或一种语言或机构 ) 如果不发展， 可能在一代人内就会消亡。"},"p15r07":{"english":"Although a dedicated reader of the book can extract & ferret out a brief chronology of Chappelle's life, the book is nevertheless not a true biography of Chappelle.","chinese":"尽管书的忠实读者可以梳理出查佩尔人生的简要时间线， 但这本书仍然不是真正意义上的查修尔传记。"},"p15r08":{"english":"The campaign official argued that the large swings in the candidate's approval ratings were a result not of the capriciousness & volatility of the electorate but rather of the polls’ margins of error and divergent methodologies.","chinese":"竞选官员认为， 候选人支持率的大幅波动并非选民的反复无常， 而是民意调查的误差范围和不同方法导致的结果。"},"p15r09":{"english":"Monarch butterflies sequester toxins in their skin to discourage predators, but black-backed orioles (lcterus abeillei) skirt & circumvent__ the defense: they consume only the soft insides of the butterfly.","chinese":"帝王媒通过在皮肤中储存毒素来阻止捕食者， 但黑背黄现 (lcterus abeillei) 巧妙避开防御; CNAB AM"},"p15r10":{"english":"Although many parents tend to be extremely critical of the public school educational system as a whole, they are reluctant to treat their children’s teachers with equal opprobrium & disdain_","chinese":"尽管许多家长往往对整个公立学校教育体系极为苛刻， 但他们不愿以同样的轻磊对待自己孩子的老师。"},"p16r01":{"english":"Asingle, cheap tablet combining a range of drugs that protect against heart disease was broached & proposed_years ago, but pharmaceutical companies were reluctant to undertake the project because it failed to provide sufficient financial incentive.","chinese":"多年前， 有人提出并建议一种结合多种预防心脏病药物的廉价单片药， 但制药公司因缺乏足够的经济激励而不愿开展该项目。"},"p16r02":{"english":"The vast majority of universities in the United States promote themselves as institutions of free speech and thought, construing censorship as antipathetic to & inconsistent with_ their search for knowledge.","chinese":"美国绝大多数大学将自己宣传为言论和思想自由的机构， 认为审查制度与追求知识背道而驰。"},"p16r03":{"english":"When called before Congress to testify about the revocation of his passport, Paul Robeson defiantly lambasted & excoriated his inquisitors for violating his rights.","chinese":""},"p16r04":{"english":"Though the art of writing was well established in Egypt and Mesopotama long before Shang period, the Chinese writing that appeared then seems to have been an entirely homegrown &","chinese":"尽管在商代之前， 埃及和美索不达米亚的书写艺术已经相当成熟， 但当时出现的中国书写似乎完全是本土的独立发展。"},"p16r05":{"english":"Although the use of cameras to study animal behavior was certainly not unprecedented & novel, cameras were nevertheless not used to study individual frogs in their natural habitat until 2009.","chinese":"尽管使用摄像机研究动物行为并非前所未有， 但直到 2009 年才开始用摄像机研究自然栖息地中的单个青"},"p16r06":{"english":"In nineteenth century Puerto Rico, the consumption of salted cod spread among the entire population; on the tables of humbler families it became a supplemental & a complementary food, adding flavor to other products and supplying much-needed protein.","chinese":"在 19 世纪的波多黎各， 咸鳃鱼的消费在整个社会中普及; 在较贫困家庭的餐桌上， 它成为一种补充性食品， 既增添了其他食材的风味， 又提供了急需的蛋白质。"},"p16r07":{"english":"Although boredom is unexceptional & commonplace, recent research indicates that excessive amounts of it can be harmful to health.","chinese":"尽管无聊是平常且普通的， 最近的研究表明， 过度的无聊可能对健康有害。"},"p16r08":{"english":"The sleight of hand of architects whose ambition is to add subtly and seamlessly to early twentieth-century Beaux Arts buildings contradicts a first principle of historic preservation: the demarcation of & lines between_ historical periods should be clear.","chinese":"建筑师们试图通过巧妙手法将早期 20 世纪美术学院派建筑进行微妙旦无颖的增补， 这种做法却违背了历史保护的首要原则: 历史时期之间的界限应当清晰。"},"p16r09":{"english":"The artist reworked certain of his etchings in order to make the scenes they depict more logical, yet, paradoxically, the pictorial space seems to become more fanciful & chimerical_the more realistically itis defined.","chinese":"这位艺术家重新修改了他的一些儿刻作品， 以使它们描绘的场景更加合乎远辑， 然而， 矛盾的是， 画面空间越是被定义得真实， 反而显得越奇幻。"},"p16r10":{"english":"The high seriousness of St. Aubyn's novel is not at all superficial; in fact, it is intrinsic to & inextricable from_the novel's ferociously comic vision","chinese":"圣奥窒小说的高度严肃性一点也不流于表面; 实际上， 它与小说猛烈的喜剧视角本质相连 、 密不可分。"},"p17r01":{"english":"The writer assumes that most people feel some version of vexed ambivalence toward large corporations: enthralled by & dazzled by the convenience they deliver yet resentful of the trade- offs that they continually demand.","chinese":"作者假设大多数人对大型企业抱有某种复杂的矛盾情感: 被其带来的便利所吸引却又对其不断要求的权衡感到不满。"},"p17r02":{"english":"Software makers typically write licensing agreements disclaiming responsibility for any negative consequences of using their products, but as computers become integrated into everything from cars to medical devices, that stance will become untenable & indefensible.","chinese":"渐融入从汽车到医疗设备的各个领域， 这种立场将变得不可维持。"},"p17r03":{"english":"‘Some species of the genus Daphnia (commonly known as water fleas) are phenotypicallyplastic & pliable, altering their diurnal migration behavior and developing exaggerated morphological defenses in response to predators","chinese":"某些水脐属物种 GEMMRAKE) 具有表型可塑性， 能够根据捕食者改变习夜迁移行为并发展出夸张的形态防御。"},"p17r04":{"english":"In many branches of science, our knowledge and technology have advanced so rapidly that new studies carried out with improved instruments and techniques may well supplant & supersede research done just twenty years earlier.","chinese":"在许多科学领域， 我们的知识和技术发展如此迅速， 以至于使用改进的仪器和技术进行的新研究很可能取代二十年前的研究。"},"p17r05":{"english":"The concept of replicability begins with the idea that the pursuit of scientific truth is not private & insular_: researchers who make claims must allow others to test those claims.","chinese":"可重复性的概念始于这样一个想法; 追求科学真理并非私密对立， 提出主张的研究者必须允许他人检验这些主张。"},"p17r06":{"english":"Travel writers have a special burden of forming [blank/] story—that is, one with a beginning, middle, and end—out of the unformed moments that make up the act of traveling.","chinese":"旅行作家肩负着特殊的任务， 要从构成旅行的和零散片段中构建一个完整的故事一一即一个有开头 、 过程和结尾的故事。"},"p17r07":{"english":"Because chemistry's position as one of the natural sciences has long seemed [blank/], historians have generally treated the foundation of chemical professorship as an inevitable component of the progression of universities.","chinese":"由于化学作为自然科学之一的地位长期以来似乎 [空白 ]， 历史学家通常将化学教授职位的设立视为大学发展过程中不可避免的组成部分。"},"p17r08":{"english":"The professor's habitual air of irascibility & exasperation was misleading front, concealing amazing reserves of patience and a deep commitment to his students’ learning","chinese":""},"p17r09":{"english":"The life of a secret agent is dangerous enough, but the life of a double agent is infinitely more precarious & perilous: a single slip can send an agent crashing to destruction.","chinese":"特工的生活已经足够危险， 而双面间谍的生活则更加闵农可危: 一次失误就可能让间谍陷入毁灭。"},"p17r10":{"english":"Even the cleverest use of time management techniques is powerless to augment & extend the sum of minutes in a person's life (over 52 million, optimistically assuming a life expectancy of 100 years ) so people squeeze as much as they could into each one of them.","chinese":"即使最巧妙的时间管理技巧也无法增加或延长一个人生命中的分钟总数 《乐观地假设寿命为 100 年， 总计超过 5200 万分钟 )， 因此人们尽可能地在每一分钟中塞满内容。"},"p18r01":{"english":"Space is often referred to as the final frontier, as the only realm of which humankind has still to gain substantial understanding, yet the ocean is also another vast area about which our knowledge is rudimentary & sketchy.","chinese":"太空常被称为人类尚未获得实质性理解的最终边疆， 但海洋同样是一个我们知识仍然粗浅的广阔领域。"},"p18r02":{"english":"Scientists should hope the faults in their theories will be discerned by & discovered by their peers since the refutation of one hypothesis can free its originator to develop a better one.","chinese":"科学家应该希望他们理论中的错误能被同行识别与发现， 因为一个假设被驱倒可以让其提出者有机会发展出更好的理论。"},"p18r03":{"english":"In the northeastern United States, beaver populations had been critically reduced or even extirpated & eliminated in large areas at the end of nineteenth century; as a result, several states instituted prohibitions on beaver trapping","chinese":"在美国东北部， 到 19 世纪末海狸种群已在大片地区被严重减少甚至根除， 因此几个州颁布了禁止捕捉海狸的规定。"},"p18r04":{"english":"Even if the story now seems a surprisingly innocuous overture to the author's later, more fully developed narrations, it anticipates & prefigures some of the key traits of those bleaker tales.","chinese":"即使这个故事现在看起来像是对作者后来更成熟叙述的一次意外平和的开场， 它也预示了一些这些更阴郁故事的关键特征。"},"p18r05":{"english":"Science is arguably a very high-minded pursuit, but that is not to say that all of its practitioners are unimpeachable & blameless, as numerous articles alleging overly generous pharmaceutical industry payments to medical researchers have tried to show.","chinese":"科学无疑是一项非常高尚的追求， 但这并不意味着所有从业者都是无可指责的， 因为许多文章试图通过揭露制药行业对医学研究人员过于慷慨的资助来证明这一点。"},"p18r06":{"english":"Some experts estimate that the recreational salmon fishery in British Columbia contributes more to the province's economy than the commercial salmon fishery does—a surprising statistic given the political commercial prominence & salience of the fishery in the province.","chinese":"人人惊讶， 考虑到该省渔业在政治上的商业重要性。"},"p18r07":{"english":"Because movie studios, under pressure to generate international sales, have favored big-budget pictures with fantasy plots, the representation of everyday domestic life has largely been left to & ceded to other media, such as television and literature.","chinese":"由于电影制片厂在压力下需要创造国际销售额， 他们更倾向于制作具有奇幻情节的大制作影片， 因此日常家庭生活的表现主要被交由其他媒体， 如电视和文学。"},"p18r08":{"english":"It's hardly faultlessness & perfection the committee calls for: rudimentary competence would be an improvement on the current chaos.","chinese":"委员会要求的并非无可挑剔的完美: 基本的能力就已经比当前的混乱状况有所改善了。"},"p18r09":{"english":"Although the essayist’s arguments did not confound & perplex her most perceptive readers, the extreme subtlety of the points she made explains why she was misinterpreted by most critics of her day.","chinese":"尽管这位散文家的论点并未让最敏锐的读者困惑， 但她所提出观点的极度微妙性解释了为何她在当时被大多数评论家误解。"},"p18r10":{"english":"Even though his opponent is currently trying to portray him as a wild-eyed radical, voters will ikely reject this charge because it does not conform to & square with his moderate political record.","chinese":"尽管他的对手目前试图将他描绘成一个极端激进分子， 选民可能会拒绝这一指控， 因为这与他的温和政治记录不符。"},"p19r01":{"english":"The laboratory maze has grown ever less intricate & convoluted since it was first invented; instead of hoping to lose a rodent in a labyrinth, today's scientists design mazes to elicit a few simple, easily measured behaviors.","chinese":"自实验室迷宫首次发明以来， 其设计已变得越来越简单; 如今的科学家不再试图让叶齿动物迷失在迷宫中， 而是设计迷宫以引发一些简单且易于测量的行为。"},"p19r02":{"english":"Members of the union’s negotiating team insisted on several changes to the company's proposal before they would support it, making it clear that they would brook & tolerate no compromise.","chinese":"工会谈判团队的成员坚持对公司提案进行多项修改， 并明确表示他们绝不妥协。"},"p19r03":{"english":"Building the first United States transcontinental phone line required fundamental innovations: for example, engineers created an amplifier for the electric signals to prevent them from attenuating & dissipating after a few miles.","chinese":"建造美国第一条跨大陆电话线路需要基础性的创新， 例如， 工程师们创造了一种电信号放大器， 以防止信号在几英里后衰减。"},"p19r04":{"english":"If aging is merely an avoidable by-product of life rather than a necessary progression, it is possible that we might eventually forestall senescence & decrepitude","chinese":"如果衰老只是生活中可以避免的副产品， 而非必然的进程， 那么我们或许最终能够阻止衰老。"},"p19r05":{"english":"We do not always use words in accordance with their dictionary definitions, for meaning often fluctuates with context: that does not mean, however, that we are completely unconstrained & free in how we use language.","chinese":"我们并不总是按照词典定义来使用词语， 因为意义常常随着语境而变化; 但这并不意味着我们在使用语言时完全没有限制或自由。"},"p19r06":{"english":"Today the chair of task force in charge of revising the psychiatric diagnostic manual is a coveted & an enviable post—people work for years to position themselves as candidates—but in the early 1970s, descriptive psychiatry was a backwater.","chinese":"如今， 负责修订精神病诊断手册的工作组主席是一个令人渴望目令人羔慕的职位一一人们花费多年努力以争取成为候选人 ---- 但在 20 世纪 70 年代初， 描述性精神病学还是一个无人问津的领域。"},"p19r07":{"english":"Since the data we have analyzed are so meager & paltry, it would be hazardous to draw a definite conclusion.","chinese":"由于我们分析的数据过于稀少， 贸然得出明确结论将是危险的。"},"p19r08":{"english":"Three of the nation’s largest airlines could be operating under bankruptcy protection in coming weeks, analysts say, the latest sign of the industry's upheaval & convulsion as it lurches through a historic transformation.","chinese":"分析人士表示， 未来几周内， 该国三大航空公司可能将在破产保护下运营， 这是该行业在经历历史性转型过程中动荡的最新迹象。"},"p19r09":{"english":"The Red Sea town of Aydhab presents scholars with a puzzle & a conundrum: medieval records describe it as a major port for ships engaged in trade, yet today there is no trace of a viable harbor at the site.","chinese":"红海小镇艾德哈布为学者们带来了一个迹题: 中世纪的记录将其描述为一个从事贸易的主要港口， 但如今该地却没有任何可用港口的痕迹。"},"p19r10":{"english":"Because the organization often trumpeted itself as a forum for temperate & dispassionate discussion, visitors were startled by the frequently heated tone of its recent debates.","chinese":"因为该组织经常宣称自己是一个冷静客观过论的论坛， 沪客们对其最近辨论中频繁出现的激烈语调感到尾"},"p20r01":{"english":"According to some political analysts, the candidate's occasionally rambling responses to questions suggest that she has been out of circulation for a while and her debating skills need to be honed & enhanced,","chinese":"根据一些政治分析人士的看法， 这位候选人偶尔漫无边际的回答表明， 她已经有一段时间未曾活跃， 她的辩论技巧需要打磨提升。"},"p20r02":{"english":"If Wilson's article style changed overtime, it was in the wrong retrograde direction, shunning & ‘eschewing experimentation and inclining toward works that seemed hobbled by a fear of risk.","chinese":"如果威尔孙的文章风格随着时间发生了变化， 那也是朝着错误的倒退方向发展， 回避实验性并倾向于那些因害怕冒险而显得受限的作品。"},"p20r03":{"english":"A small degree of emendation & revision is always desirable in a published diary. A sense of authenticity is seldom worth the diarists questionable grammar or careless phrasing,","chinese":"在已出版的日记中， 适度的修订总是值得提倡。 真实性的意义往往不及作者可疑的语法或随意的措辞重"},"p20r04":{"english":"Inher career as an editor, she pruned and shaped many a writer's [blank/] prose into crisp lucidity.","chinese":"在她作为编辑的职业生涯中， 她将许多作家的文字修萤打磨成清晰流轧的表达。"},"p20r05":{"english":"Every illness is a story, and when Annies began it was characterized by the kinds of unexceptional & nondescript details that mean nothing until seen in hindsight.","chinese":"每种疾病都是一个故事， 而安妮的病刚开始时， 充满了那些平凡无奇的细节， 这些细节在事后回想时才显得意义非凡。"},"p20r06":{"english":"The brain has become, for many people, tantamount to & synonymous with the biological machinations of the self, and the self-knowledge promised by neuroscience has ignited a hunger to understand how new findings weigh in on age-old questions.","chinese":"对于许多人来说， 大脑已然等同于自我生物机制， 而神经科学所承诺的自我认知激发了人们渴望了解新发现如何影响那些古老问题的热情。"},"p20r07":{"english":"It's true that occasional verbose & long-winded entries might have been edited without damaging the diarys overall impact, but the very completeness of Clara's eloquent reflections conveys a strong sense of the density of a young woman's experiences.","chinese":"确实， 偶尔宛长的条目可能被编辑过而未损害日记的整体影响， 但克拉拉完整而富有表现力的反思充分展现了一位年轻女性经历的丰富性。"},"p20r08":{"english":"In spite of her fascination with chance, coincidence, and contingency, Stanning's novels are painstakingly & meticulously constructed, written from the head rather than the heart","chinese":"尽管斯坦宁对偶然 、 巧合和意外充满着迷， 她的小说却是精心构建的， 更注重理性而非感性。"},"p20r09":{"english":"Matsui is an extremely shrewd & canny political tactician, as she generally will withhold her support for a political faction or a policy until she is confident it will prevail.","chinese":"松井是一位极其精明的政治策略家， 她通常会在确信某个政治派别或政策能够获胜后才给予支持。"},"p20r10":{"english":"The notion's pedigree & origin notwithstanding—it was first proposed by a Nobel Prize-winning physicist—it was neglected for many years until some unexpected observations led to its revival.","chinese":"尽管这一概念的 _、 渊源与起源 _ 一一最初由一位诺贝尔奖获得的物理学家提出 -一被忽视了许多年， 直到一些意外的观察使其得以复兴。"},"p21r01":{"english":"Itis commonly said that each persor’s aesthetic taste is distinct & idiosyncratic, yet that notion overlooks a large body of shared aesthetic preferences.","chinese":"人们常说， 每个人的审美品味都是独特的， 但这一观点忽略了大量共同的审美偏好。"},"p21r02":{"english":"In spite of being one of the world's biggest purveyors & suppliers of fossil fuels, the firm has made some environmentally responsible investments","chinese":"尽管该公司是全球最大的化石燃料供应商之一， 但它已进行了一些环保投资。"},"p21r03":{"english":"Many macroscopic or higher-level properties on the basis of which we sort chemicals into types are not inherent in & intrinsic to the chemical structure itself but instead only manifest themselves under certain conditions or in particular contexts.","chinese":"许多我们用来将化学物质分类的宏观或高层次特性并非化学结构本身所固有， 而是仅在特定条件或特定情境下才会显现。"},"p21r04":{"english":"Many types of rocks contain small voids that dampen & impede_vibrations: the greater proportion of a rock's volume that is void, the more gradually vibrations travel through it.","chinese":"许多类型的岩石包含能够减级振动的小空除: 岩石中空隐所占体积比例越大， 振动传播得越慢。"},"p21r05":{"english":"Journal editors note that the peer review process has difficulty detecting fraud & duplicity__: deliberate misinformation, if it is clever enough, might sail right through no matter how scrupulous the reviews.","chinese":"期刊编辑指出， 同行评审过程难以发现欺诈: 如果刻意的虚假信息足够巧妙， 无论审查多么严格， 都可能轻易通过。"},"p21r06":{"english":"Beauford Delaney's dynamic depictions of Harlem and Greenwich Village, dating from 1929 to. 1953, convey & impart__ the energy of the city, while the equally captivating abstract compositions from his Paris years of 1953 to 1979 demonstrate his sustained exploration of color.","chinese":"比福德 ' 德拉尼从 1929 年至 1953 年对哈莱姆和格林尼治村的生动描绘展现了城市的活力， 而他在 1953 年至 10 让 ROO HESIPE?! 人 EB ah Se 4 2h AI 22 SSS"},"p21r07":{"english":"The senator complained that the president's argument against the provision was specious & deceptive, gaining its apparent plausibility from a distorted presentation of the relevant data","chinese":"参议员抱忽总统反对该条款的论点是虚假且具有欺骗性的， 其表面上的合理性来源于对相关数据的扭曲呈"},"p21r08":{"english":"In a production process that is complex and often unpredictable, roles that start out discretely defined may become quite fluid & mutable_.","chinese":"在复杂且常常不可预测的生产过程中， 起初明确定义的角色可能会变得相当灵活多变。"},"p21r09":{"english":"There's a splendor & a sumptuousness__ throughout the Broadway adaptation of The Color Purple that, while hardly true to the harrowing bleakness of the early chapters of Alice Walker's novel, does bring to mind the enjoyable hokey cinematic lavishness of the film version.","chinese":"百老汇版 (RE) 的改编贯穿着一种辉煌与奢华， 虽然与爱丽丝. 沃克小说开篇的凄惨阴郁相去其远， 但确实让人联想到电影版中令人愉悦的俗气华丽。"},"p22r01":{"english":"In hindsight, itis easy to say that the geological evidence for ice ages was overwhelming & irresistible_and to wonder why such periods in the Earths past were not recognized earlier.","chinese":"事后看来， 很容易说冰河时代的地质证据是压倒性的， 并且令人无法抗拒， 并且想知道为什么地球过去的这些时期没有被更早地发现。"},"p22r02":{"english":"Tender yet never saccharine & cloying, the memoir engages the reader without resorting to cliches","chinese":"温柔却从不甜腻， 这本回忆录吸引读者而不落俗套。"},"p22r03":{"english":"The auditors are relying on the failing bank to make changes that it has steadfastly resisted for years and even now does not seem impatient & keen_to carry out.","chinese":"审计人员依赖这家濒临倒闭的银行做出其多年来始终拒绝的改变， 而即使是现在， 它似乎也并不急切三意执行。"},"p22r04":{"english":"Developments in neuroscience and animal behavior have led researchers to question the view that unmitigated competition is essential in & foundational to__ animal life: in primatology, the countermovement started with research into how friendships and conflict resolution favor survival.","chinese":"神经科学和动物行为学的发展使研究人员开始质疑无条件竞争是否是动物生活中不可或缺且基础性的: 在"},"p22r05":{"english":"The author first accused the official of espionage in a 1981 book, and-though the case was far from unassailable & airtight, full of suppositions rather than compelling evidence-the accusation has been repeated relentlessly ever since.","chinese":"作者在 1981 年的一本书中首次指控该官员从事间谍活动， 尽管这一案件远非无人可击， 充满了假设而非令人信服的证据， 但这一指控自那时起便被不断重复。"},"p22r06":{"english":"This book indulges in a number of convenient fictions & inventions, including its dubious timeline and its veneer of collective authorship.","chinese":"这本书沉溺于许多便利的虚构与创造， 包括其可疑的时间线和集体创作的表面伪装。"},"p22r07":{"english":"The author argued that the industrial agricultural system that prevails in the United States is unsustainable and, therefore, anything that reinforces & buttresses it should be questioned.","chinese":"作者认为， 美国盛行的工业农业体系是不可持续的， 因此任何 _” 强化支持 _ 它的事物都应该受到质疑。"},"p22r08":{"english":"Tao Zhu and Yaobin Lu found that personality traits can affect user adoption of mobile commerce, suggesting that a mobile service provider could benefit from partitioning & segmenting the market, specifically targeting extroverts, for instance.","chinese":"陶竹和卢逃斌发现， 个性特质会影响用户对移动商务的采用， 这表明移动服务提供商可以通过细分市场， 特别是针对外向型用户， 从中获益。"},"p22r09":{"english":"The fact that no single Cantonese dictionary is seen as authoritative & definitive is one of the main reasons why most Hong Kong authors do not depend on formal reference tools when writing in Cantonese.","chinese":"没有任何一本粤语词典被视为权威且最终定论， 这正是大多数香港作者在用粤语写作时不依赖正式参考工具的主要原因之一。"},"p23r01":{"english":"While other authors surelyinfluenced & informedAmerican novelist Toni Morrison's literary style, there really was no precedent for the sorts of books she conceived","chinese":""},"p23r02":{"english":"Throughout human history, intelligence and consciousness have beenallied & conflated concepts: those possessing much of the former are assumed, in some ill-defined way, to be more conscious than those less astute.","chinese":"纵观人类历史， 智慧与意识一直是密不可分的概念: 拥有更多智意的人通常被模糊地认为比不那么聪明的人更有意识。"},"p23r03":{"english":"The indigenous uprising in Bolivia in 2008 was notunprecedented & unique_: in 1781 indigenous people took over the area near present-day La Paz in what constituted the biggest challenge to the Spanish who then controlled Bolivia.","chinese":"2008 WAAL ARERR HAERPIAA: 1781 年， 原住民占领了现今拉巴斯附近的地区， 这构成了当时对控制玻利维亚的西班牙人最大的挑战。"},"p23r04":{"english":"‘The Chippewa regarded their treaties with the federal government as solemn covenants and therefore, throughout the twentieth century, met efforts by governmental officials toabrogate & nullify_those treaties with both open and hidden resistance.","chinese":"奥吉布瓦人将他们与联邦政府签订的条约视为神圣契约， 因此， 在整个二十世纪， 他们对政府宫员试图废除这些条约的努力进行了公开和隐秘的抵抗。"},"p23r05":{"english":"It can be a daunting task to plunge into the disparate and extensive data sets on the carnivores and distill & extract_ meaningful patterns from their extraordinary morphological, behavioral, and ecological diversity.","chinese":"深入研究食肉动物的不同且广泛的数据集， 并从其非凡的形态 、 行为和生态多样性中提炼出有意义的模式， 可能是一项艰巨的任务。"},"p23r06":{"english":"Judge Jones brought some welcome levity to the often tense, though sometimestedious & tiresome_, proceedings.","chinese":"琼斯法官为通常紧张但有时乏味的诉讼带来了一些令人愉快的轻松气氛。"},"p23r07":{"english":"人 Akey characteristic in the author's presentation of his character's dreary life is economy & concision_: paragraphs are short, sentences are laconic, patterns of repetition and circularity are evoked by means of symbolic shorthand.","chinese":"作者在呈现其角色沉问生活时的一个关键特点是简洁: BSS, FRM, BRS me 重复和循环的模式。"},"p23r08":{"english":"Nancy Weiss Malkiels painstakingly detailed history of coeducation at elite universities is an invaluable antidote to & corrective to_ the amnesia that has come to envelop even such a relatively recent-but critically neglected-development.","chinese":"南希. 韦斯: 马基尔对精英大学男女同校历史的详尽研究， 是对遗忘这一相对较近但却被严重忽视的发展的一剂良药与纠正。"},"p23r09":{"english":"JIn denying him a promotion, management cited his capricious & cavalier_decision making, charging that his judgments were based on vagaries rather than careful forethought.","chinese":"在拒绝给他升职时， 管理层指出他决策的随意与草率， 指责他的判断基于变化无常而非深思熟虑。"},"p23r10":{"english":"All of his previous efforts at ingratiating himself with the official were nullified & vitiated when he responded antagonistically to the official's goading,","chinese":""},"p24r01":{"english":"Astute and incisive, the essayist’s work was nevertheless civil and polite: the essayist either had no gift of vitriol & obloquy_or else never felt any.","chinese":"敏锐而深刻， 这位获文家的作品却始终文雅有礼: 要么是完全不具备尖酸刻薄的天赋， 要么是从未感受到"},"p24r02":{"english":"Though initially presented in a blaze of hyperbole, the thesis is repeated even more soberly & sensibly in the ensuing paragraphs.","chinese":""},"p24r03":{"english":"Although technically their members were hunter-gatherers, many early Native California communities exhibited traits more typically associated with well-developed agrarian societies and, therefore, are often presented in the ethnographic literature as anomalous & exceptional,","chinese":"尽管从技术上讲， 他们的成员是狩猎采集者， 许多早期的加州原住民社区表现出更常与发达农业社会相关的特征， 因此在民族志文献中经常被描述为异常。"},"p24r04":{"english":"An academic with a questionable record in either teaching, administration, or research may still be well regarded at many schools, but simultaneous failure in all three areas normally results in disapprobation & censure by superiors.","chinese":"一名在教学 、 行政或研究方面记录存疑的学者可能仍会在许多学校受到好评， 但在这三个领域同时失败通常会导致上级的非难。"},"p24r05":{"english":"The author's latest novel may placate & appease those who generally spurn her writing: its unvarnished prose has little in common with the labyrinthine interior explorations of her earlier work.","chinese":"作者的最新小说可能会安抚那些通常排斥她作品的人: 其质朴的文笔与她早期作品中复杂的内心探索几乎"},"p24r06":{"english":"In his heyday, Sonny Bono's role in public was protean & versatile: he was an accomplished lyricist, a mayoral success story, delegate from Palm Springs, and the husband of an internationally acclaimed vocalist.","chinese":"NMEA, RE MBEARAHRBSASE: 他是一个才华横溢的作词人 、 一位成功的市长 、 棕榈泉的代表， 以及一位国际知名歌手的丈夫。"},"p24r07":{"english":"It may not seem like a big deal for produce distributors to mix together soybeans from different farms, but a growing number of buyers are willing to pay a premium for soybeans the origin & provenance of which is know: they like to know exactly where their food came from.","chinese":"对于农产品分销商来说， 将不同农场的大豆混合在一起似乎不是什么大问题， 但越来越多的买家愿意为明确 _ 来源 _ 的大豆支付溢价: 他们和希望确切知道自己的食物来自哪里。"},"p24r08":{"english":"The historical study of pregnancy and childbearing began fairly recently and has been hindered by the relative dearth & paucity_of records concerning these particular experiences","chinese":"怀孕和分娩的历史研究开始得相对较晚， 并且由于相关经历记录的相对稀缺而受到阻碍。"},"p24r09":{"english":"The university's once [blank/] department of economic history has lost prestige and transmogrified into a department of management and marketing.","chinese":""},"p24r10":{"english":"Although field studies have linked inbreeding to declines among song sparrow populations, some researchers argue that, in nature, inbreeding proves trivial & inconsequential as a factor when ‘compared with crushing blows from weather changes.","chinese":"尽管实地研究将近亲繁殖与画眉乌种群歼量下降联系起来， 一些研究人员认为， 与天气变化带来的沉重打击相比， 近亲繁殖作为一个因素显得微不足道。"},"p25r01":{"english":"Any notion of justice in the fortunes of artists is baseless & untenable: works of equal value and quality produce quite different returns or no returns at all.","chinese":"任何关于艺术家命运中正义的概念都是刻无根据且站不住肢的: 同等价值和质量的作品会产生截然不同的回报， 甚至根本没有回报。"},"p25r02":{"english":"The book brings together many valuable reports on conservation projects, but with less variety than might have been wished: nearly half the contributions are from the same state, and consequently, the case studies are similarly restricted & circumscribed geographically.","chinese":"这本书汇集了许多关于保护项目的宝贵报告， 但种类不如预期丰富: 近一半的内容来自同一个州， 因此案例研究在地理上同样受到限制。"},"p25r03":{"english":"Because its previously quixotic & idealistic beliefs had become core tenets of mainstream politics, the activist group disbanded; with no more skeptics to persuade, its purpose had evaporated.","chinese":"由于其先前充满幻想的理想信念已成为主流政治的核心原则， 该激进组织解散了; 因为再也没有怀疑者需要说服， 其存在的意义已不复存在。"},"p25r04":{"english":"Although its director asserts & maintains that the movie uses a documentary approach in portraying the famous sit-down strike, in practice its characters are heavily fictionalized and fall into familiar Hollywood types.","chinese":"尽管导演声称电影以纪录片的方式展现了著名的静坐罢工， 但实际上其中的角色被高度虚构， 并落入了典型的好莱坞模式。"},"p25r05":{"english":"Tompkinson’s prior donations to the university, while very generous, failed to portend & predict_ the magnitude of her latest gift.","chinese":"汤普金森之前对大学的捐赠虽然非常情慨， 但未能预示她最新一笔捐赠的巨大规模。"},"p25r06":{"english":"In ways large and small, millions of people are taking active steps to sidestep & circumvent the medical mainstream, whether by taking herbal remedies for disease or by placing their hopes for a cure in alternative treatment.","chinese":"无论是大事还是小事， 数百万人正积极采取行动 _ 避开主流医疗 _， 无论是通过使用草药治疗疾病， 还是寄希望于蔡代疗法。"},"p25r07":{"english":"An apparent paradox led the scientists to pursue their present line of research. They were struck by the fact that a single mathematics formula can be used to describe physical phenomena that appear to be so heterogeneous & dissimilar.","chinese":"一个明显的悖论促使科学家们开展了他们当前的研究方向。 他们惊讶于一个数学公式竞然可以用来描述看似如此异质且不同的物理现象。"},"p25r08":{"english":"Architects may be more extroverted and therefore the more visible & salient members of a bridge design team, but they are not always the most essential","chinese":"建筑师可能更外向， 因此是桥梁设计团队中更显眼的成员， 但他们并不总是最重要的。"},"p25r09":{"english":"Citing the corruption and intrigue that pervaded politics in the city, my colleague slighted & disparaged the newspaper's trove of journalism prizes, declaring that finding great stories in the city must be effortless.","chinese":"引用了城市政治中普遍存在的腐败和阴谋， 我的同事轻视报社获得的大量新闻奖项， 声称在这座城市中发现好故事一定豪不费力。"},"p25r10":{"english":"Explorers could not build each other's knowledge if they could not trust records of previous explorers; thus exploration depended on the exactitude & meticulousness of those who had gone before.","chinese":"如果探险者无法信任前人记录， 就无法相互建立知识; 因此， 探险依赖于前人记录的准确无误。"},"p26r01":{"english":"Scientist reported last month on a sign of relative solar quiescence & calm & calm; the solar wind, a rush of charged particles continually spewed from the Sun at a million miles an hour, had diminished to its lowest level in 50 years.","chinese":"科学家上个月报告了一个相对太阳平静的迹象;以每小时百万英里的速度不断从太阳喷出的带电粒子流一一太阳风， 已降至 50 年来的最低水平。"},"p26r02":{"english":"Wilson is wont to emphasize the beneficence & altruism of ants, how ants with full stomachs will regurgitate liquid food for those without, or how the old will fight so the young can survive.","chinese":"威尔逊常常强调蚂蚁的仁慈与无私， 例如饱腹的妈蚁会将液体食物吐给饥饿的同伴， 或者年老的蚂蚁会奋战以保护年轻的蚂蚁生存。"},"p26r03":{"english":"In matters of taste, the art patron and collector Peggy Guggenheim was an extremist & a zealot, she was for the strangest, the most surprising, the most satisfying, the best, the unique.","chinese":"在品味方面， 艺术赞助人兼收藏家佩吉. 古根海姆是个极端分子， 她追求最奇特 、 最令人惊讶 、 最令人满足 、 最优秀 、 最独特的事物。"},"p26r04":{"english":"The employee had a reputation for fractiousness, but his coworkers found him to be, on the contrary, quite affable & easygoing","chinese":"这名员工以易怒著称， 但同事们却发现他恰恰相反， 非常随和。"},"p26r05":{"english":"The performer can be inflammatory & provocative in his comedy, but he is fundamentally a bighearted person who displays a core sweetness even at his most manic.","chinese":"这位表演者的喜居可能充满煽动性和挑是性， 但他本质上是一个心地善良的人， 即使在他最狂热的时候也展现出内心的温暖。"},"p26r06":{"english":"Edited collections of scholarly essays generally tend to be somewhat uneven: they suffer from the heterogeneous & disparate subject matter of the various essays, the lack of an overarching and consistent thesis, and the variable quantity of the contributions.","chinese":"学术论文的编辑合集通常会显得有些参差不齐: 它们受到各篇论文内容 _ 杂乱无章 _ 的影响， 缺乏一个总体一致的论点， 且各篇贡献的质量也不尽相同。"},"p26r07":{"english":"Ursula Le Guin claims that looking at schoolbooks from around 1900 can beintimidating & scary, given that the level of literacy and general cultural knowledge expected of a mere ten-year-old was,","chinese":""},"p26r08":{"english":"The historian argued thathypotheses & preconceptions are essential to science, claiming that these inherited and untested beliefs often form the conceptual framework necessary for further research.","chinese":"历史学家认为 ”假设与途见 _ 对科学至关重要， 并声称这些继承且未经验证的信念通常构成进一步研究所"},"p26r09":{"english":"One can only bemoan how the wonderfully rich collections of genuine fossil specimens seen of yore in museum displays are being replaced by the showy & meretricious talking plastic of so- called virtual reality.","chinese":"人们只能哀叹， 博物馆展览中曾经展示的那些极其丰富的真实化石标本， 如今正被所谓虚拟现实的浮华塑料所取代。"},"p26r10":{"english":"Spiderwebs suspended on flexible supportswaver & oscillate even in low airflow in patterns that are erratic, enhancing the probability of insect capture over a volume of space.","chinese":"起挂在荣性支架上的疯蛛网即使在低气流中也会摇摆晃动， 其不规则的运动模式堪加了在空间范围内梢捉昆虫的概率。"},"p27r01":{"english":"The archives of the museum, containing a plethora of documents that shed light on Picasso's work, may, for a time, give us the illusion of total comprehension, but in the end it seems that Picasso is no moreunderstandable & transparent than he ever was.","chinese":"博物馆的档案馆中保存着大量揭示毕加索作品的文件， 这些文件或许会在一段时间内让我们产生完全理解的错觉， 但最终看来， 毕加索似乎仍然和过去一样难以理解且不透明。"},"p27r02":{"english":"Origin, distribution, and habitat are included in the book for some but not all of the plants; offering this information for each species would have given readers a clearer appreciation of the differences between endemic & native & native and introduced species.","chinese":"书中包含了一些但并非所有植物的起源 、 分布和栖息地信息; 如果为每个物种提供这些信息， 将能让读者更清楚地理解特有种 、 本地种和外来种之间的差异。"},"p27r03":{"english":"In their quest for kinder cutting, physicians increasingly rely on endoscopic surgery, replacing large scalpels and clamps with cameras and flexible & supple tools that snake into the body through tiny holes.","chinese":"在追求更温和的手术方式时， 医生越来越依赖内帘镜手术， 用摄像头和灵活工具代蔡大型手术刀和夹子， 这些工具通过微小的孔进入体内。"},"p27r04":{"english":"Her apparent unfamiliarity with & ignorance of her background and ancestry seems unconceivable in an age when people tend to think of themselves to exhaustion.","chinese":"她显然对自己的背景和祖先毫无了解， 这在一个人们倾向于过度思考自我的时代似乎难以置信。"},"p27r05":{"english":"Appearing in the midst of so many equivocal comments, this unambiguous statement, whatever its intrinsic merit, plainly stands out as anomalous & unusual.","chinese":"在众多模棱两可的评论中， 这一明确的声明无论其本身价值如何， 显然显得格外异常。"},"p27r06":{"english":"The baseball players performance during last night's game was impressive, although not unexampled & novel; others have performed similar feats.","chinese":"了昨晚比赛中棒球运动员的表现令人印象深刻， 尽管并非前所未有; Rib ths Sway,"},"p27r07":{"english":"Itis normal for artists who achieve great acclaim during their lifetimes to be considered outmoded & unfashionable shortly after their deaths, only to have their reputations restored by subsequent generations.","chinese":"艺术家在生前获得巨大赞誉后， 去世后不久被认为过时且不流行， 而后又被后代重新评价， 这是正常现"},"p27r08":{"english":"Many scholars studying leadership decry & condemn cult of the celebrity that has been fostered both by the media and by politicians’ public relations staffs, arguing that it trivialized politics.","chinese":"许多研究领导力的学者退责媒体和政治家公关团队助长的名人崇拜， 认为这使政治变得肤浅。"},"p27r09":{"english":"Itis troubling that blogs, which may be among the least reliable sources of information in human history, occupy such conspicuous & prominentpositions in Intemet search engine results.","chinese":"令人不安的是， 博客可能是人类历史上最不可靠的信息来源之一， 却在互联网搜索引擎结果中占据如此显眼的位置。"},"p27r10":{"english":"The actor's part in the film turned out to be trivial & inessential: he had only one line, and by the time the film appeared in theaters, even that line had been removed,","chinese":"这位演员在电影中的角色结果是无关紧要的: 他只有一句人台词， 而当电影上映时， 连那句台词都被油掉"},"p28r01":{"english":"Although eager & keen to please his audiences, Mozart was, at the same time, fully aware of his musical genius and had no intention of compromising his music.","chinese":"尽管莫扎特 _ 渴望 _ 取悦观众， 但他同时完全意识到自己的音乐天才， 并无意肌协自己的音乐。"},"p28r02":{"english":"The series of documentaries certainly does not promote the country's recent diplomatic initiatives; in fact, some of the films appear to be denunciations of & indictments of those initiatives.","chinese":"这些纪录片系列显然并未宣传该国最近的外交举措; 事实上， 其中一些影片似乎是对这些举措的遗责。"},"p28r03":{"english":"The story lines of silent dramas may often have been rudimentary & elemental, yet within those basic narrative outlines, the true artists among silent-film actors could express emotional shadings that have no analogue in spoken language.","chinese":"无声戏剧的故事情节可能常常是粗浅单薄的， 但在这些基本的叙事框架中， 无声电影演员中的真正艺术家能够表达出无法用语言描述的情感层次。"},"p28r04":{"english":"Given the plethora & surfeit of solid case studies of environment degradation, this new study adds very little to our knowledge of the field.","chinese":"鉴于环境破坏已有大量扎实的案例研究， 这项新研究对该领域的认识几乎没有新增贡献。"},"p28r05":{"english":"Itis surprising to see such a child that is at his sixteenth manifest a great measure of maturity & precociousness, for he delivers too cogent, brilliant a speech among adults.","chinese":"令人惊讶的是， 这样一个十六岁的孩子表现出极大的成熟， 能够在成年人中发表如此有说服力且精彩的演"},"p28r06":{"english":"One big challenge with placebo responses is that they are capricious & unpredictable: people given the same inert pill or potion may show wildly different reactions, and the effects vary widely according to each person's illness.","chinese":"一个主要的挑战是安慰剂反应具有不可预测性: 服用相同无效药物的人可能表现出截然不同的反应， 而且效果因每个人的疾病而异。"},"p28r07":{"english":"His political view, harking back to the turmoil in the 1934, is a relic & vestige with no bearing on the present.","chinese":"他的政治观点可以追溯到 1934 年的动荡， 是与当下无关的选迹。"},"p28r08":{"english":"Despite its best efforts to stimulate sales, the bookselling business remains far from healthy & robust, for it has high fixed costs in wages and rent, and falling prices make these ever harder to spur.","chinese":"尽管尽最大努力刺激销售， 图书销售行业仍然远未达到健康强劲的状态， 因为工资和租金的固定成本很高， 而价格下降使这些成本更难以推动。"},"p28r09":{"english":"Peoples decisions about childbearing depend on innumerable personal consideration and societal factors, yet even knowing this, demographers are often flummoxed & confounded: their projections of birth rates frequently turn out to be embarrassingly at odds with reality.","chinese":"人们关于生育的决定取决于无数个人考量和社会因素， 然而即使知道这一点， 人口统计学家仍常常感到困惑: 他们对出生率的预测往往与现实大相径庭， 令人和尴人这。"},"p28r10":{"english":"There is a cryptic & an elusive quality to Beryl Bainbridge’s best novels, what Hilary Martel calls “an air of mystery, as if something has been inked in and then sponged away, leaving a faint trace for the reader to pick up”.","chinese":"贝丽尔. 贝恩布里奇最好的小说具有一种神秘莫测的特质， 正如和希拉里. 受特尔所说:“ 带着一种神秘感， 仿人蚀某些东西被描绘出来后又被擦去， 只留下淡淡的痕迹供读者捕捉。"},"p29r01":{"english":"While merchants and bankers in thirteen-century Europe quickly embraced the Hindu-Arabic numeral system, the governing authorities were less captivated by & enamored of it.","chinese":"尽管 13 世纪欧洲的商人和银行家迅速接受了印阿数字系统， 统治当局却不那么着迷。"},"p29r02":{"english":"Jaime Javier Rodriguez notes that popular art forms often conceal a daunting complexity: frequently what appears canned & formulaic becomes intricate and challenging when closely examined.","chinese":"Jaime Javier Rodriguez 指出， 流行艺术形式常常隐藏着令人望而生畏的复杂性: 许多看似刻板的内容在深入研究时会变得复杂且具有挑战性。"},"p29r03":{"english":"Every serious attempt at a historical portrait of the past will subtly absorb the milieu and temperament of its living author, however objective & impartial he or she sets out to be.","chinese":"每一次对过去历史画像的严肃尝试， 无论作者起初多么客观公正， 都会微妙地吸收其生活环境和性情。"},"p29r04":{"english":"Although we no longer have to rely on salt to keep food from spoiling, our appetite for it is unabated & undiminished: most people eat much more salt than they need","chinese":"尽管我们不再需要依赖盐来防止食物变质， 但我们对盐的需求依然不减: 大多数人摄入的盐远超所需。"},"p29r05":{"english":"When it comes to arriving at brilliant ideas, filtering out distractions might well be deleterious & counterproductive: if a person's mind is wandering, that person tends to outperform peers ina range of tasks in which flashes of insight are important.","chinese":"当涉及到产生出色的想法时， 排除干扰可能会适得其反: 如果一个人的思维在游萝， 那么在需要灵感闪现的一系列任务中， 这个人往往表现优于同龄人。"},"p29r06":{"english":"Robbins’ accomplishment is not a trivial & an insignificant one: her book makes the topic accessible to a general audience while still providing the sort of analysis that scholars demand.","chinese":"罗宾斯的成就绝非微不足道; 她的书使这一主题对普通读者来说易于理解， 同时也提供了学者所要求的那种分析。"},"p29r07":{"english":"The fact that most hypotheses tum out to be wrong does not mean that hypothesizing is futile & fruitless. in fact, most hypotheses include useful ideas that survive to become part of the next model or scenario.","chinese":"大多数假设被证明是错误的这一事实并不意味着假设是徒劳无益的。 事实上， 大多数假设都包含有用的起法， 这些想法会被保留下来， 成为下一个模型或情景的一部分。"},"p29r08":{"english":"Eschewing today's hovered-over kids as less plausible characters for an adventure story, Rebeca Stead set her new children's novel in nineteen-seventies New York to show children with a great deal of autonomy & independence","chinese":"为了避免当今被过度关注的孩子们在冒险故事中显得不够真实，Rebeca Stead 将她的新儿童小说设定在 20 世纪 70 年代的纽约， 以展现拥有高度自主性的孩子们。"},"p29r09":{"english":"Most of the drugs used to treat celiac disease that are now in development would not eliminate the need for a gluten-free diet but would help allay & palliate & allay symptoms when some gluten is unintentionally ingested.","chinese":"时， 可以帮助缓解症状。"},"p29r10":{"english":"Other monarchs have been accused by posterity of murder and treason without having come to be regarded with such opprobrium & infamy, perhaps because the cases against them have never been satisfactorily proved.","chinese":"其他君主虽被后世指控谋杀和上类国， 但却未因此受到如此恶名， 或许是因为针对他们的指控从未得到令人信服的证明。"},"p30r01":{"english":"Itis rare for a prominent member of the company to leave without some acrimony & bitterness. Smith, who resigned with civility, is an exception","chinese":""},"p30r02":{"english":"Despite dogs’ talent for detecting those high-pitched whistles that are inaudible to us, dogs’ ability to locate sounds is imprecise & inexact compared with ours.","chinese":"尽管狗能察觉我们听不见的高频哨声， 但它们定位声音的能力相比我们却不够精确。"},"p30r03":{"english":"Because it has usually been impossible to eradicate exotic species once they have become established, itis prudent & provident to minimize introductions of species that have substantial probabilities of unwanted impacts.","chinese":"由于外来物种一旦定居通常难以根除， 因此尽量减少可能带来不良影响的物种引入是明智的。"},"p30r04":{"english":"He found his new acquaintance to be unfathomable & inscrutable__: trying to understand her personality was like peering into an unknown dimension","chinese":"他发现新认识的人深不可测: 试图了解她的性格就像在窥探一个未知的维度。"},"p30r05":{"english":"A telescope orbiting in space, above the unruly atmosphere, is able to detect ultraviolet and infrared emissions that are blocked by Earths atmosphere and thus indiscernible & imperceptible_to astronomers on the ground.","chinese":"在太宝中轨道运行的望远镜位于混乱的大气层之上， 能够探测到被地球大气阻挡 、 因此地面天文学家无法察觉的紫外线和红外线辐射。"},"p30r06":{"english":"The series of documentaries certainly does seem to promote the country's recent diplomatic initiatives; in fact, some of the films appear to be tributes to & encomiums to_those initiatives.","chinese":"这系列纪录片确实似乎在宣传该国最近的外交举措; 事实上， 其中一些影片似乎是对这些举措的殉美。"},"p30r07":{"english":"To say that John Adams was forthright was to be charitable & forbearing_; friends as well as enemies were more likely to characterize his stark honesty and direct manner as blunt and awkward.","chinese":"说约翰亚当斯直率是宽容; 无论是朋友还是牧人， 更可能将他的直白和直接的态度描述为生硬和答拙。"},"p30r08":{"english":"One early sign of this new thirst for probity & integrity is the fact that eight members of the committee on professional conduct have already recused themselves in the name of unbiased justice","chinese":"这种对廉洁正直的新渴望的一个早期迹象是， 专业行为委员会的八名成员已经以公正无偏的名义主动回"},"p30r09":{"english":"Researchers concluded that although the success of pearl millet crops in the region varied with seasonal climatic conditions, cultivation remains advantageous & expedient because of pearl millets predisposition to perform under stressful growing conditions, including drought.","chinese":"的恶劣生长条件下表现优异， 其种植仍然具有优势。"},"p30r10":{"english":"Faced with so much conflicting information on the internet, many people come to believe that all sources are so slanted & tendentious_that efforts to discriminate between the true and the false are inevitably futile.","chinese":"面对互联网上如此多相互矛盾的信息， 许多人开始相信所有来源都如此偏颇， 以至于辨别真伪的努力不可避免地徒劳无功。"},"p31r01":{"english":"Only novel ideas should be awarded patents; if a concept is manifest & obvious_to practitioners in a given field or has previously been published in almost any fashion, that fact should invalidate the application.","chinese":"只有新颖的想法才应被授予专利; 如果某个概念对该领域的从业者来说显而易见或以任何形式已被公开发表， 那么这一事实应使申请无效。"},"p31r02":{"english":"Because they view Earth's resources as strictly limited, some environmentalists find the notion of sustainable growth to be questionable & dubious_, believing that self-restraint and sacrifice must be at the heart of any environmentally sound strategy for the future.","chinese":"由于他们认为地球资源是严格有限的， 一些环保主义者认为可持续增长的概念是值得怀疑的， 认为任何符合环保的未来战略都必须以自我克制和牺牲为核心。"},"p31r03":{"english":"Because wildfires are becoming increasingly atypical & idiosyncratic, the computer modeling programs that used to help predict their progression based on information about past fires are becoming less useful to those engaged in fighting the blazes.","chinese":"由于野火正变得越来越反常， 过去基于以往火灾信息来预测其发展趋势的计算机建模程序对扑灭火灾的人来说变得不再那么有用了。"},"p31r04":{"english":"Fungi are a basic component of every ecosystem, and their importance cannot be gainsaid & disputed, but mycologists generally lack an understanding of which fungi are present in oceans and what roles they play.","chinese":"真菌是每个生态系统的基本组成部分， 其重要性不可否认， 但真菌学家通常缺乏对海洋中存在哪些真菌及其作用的了解。"},"p31r05":{"english":"‘Some renewable energy technologies are quite mainstream & conventional: for example, hydro power from dams and rivers has been a source of power generation since the early 1900s, and today it supplies sixteen percent of electricity worldwide.","chinese":"一些可再生能源技术相当主流: 例如， 水坝和河流的水力发电自 20 世纪初以来一直是电力生产的来源， 如今它为全球提供了 16% 的电力。"},"p31r06":{"english":"Orbiting Jupiter just beyond Europa, the giant moon Ganymede—bigger than the planet Mercury— appears rather inert & dormant on the outside, but it may be warm and active within,","chinese":"环绕在木星周围 、 位于欧罗巴之外的巨大卫星盖尼米德一一比水星还大一一外表看似相当沉让， 但其内部可能温暖且活跃。"},"p31r07":{"english":"Dogs intake of olfactory information is lesspunctuated & Intermittentthan that of humans because dogs exhale through the side slits of their nostrils, keeping a continuous flow of inhaled air in their snouts for smelling.","chinese":"狗对嗅觉信息的摄取比人类更连续， 因为狗通过鼻孔侧边的终隙呼气， 从而在鼻腔中保持持续的吸入气流"},"p31r08":{"english":"Wilson sees the ideas that he presents in his new book as being notably iconoclastic & subversive, but his critics, by contrast, claim that they are actually rather conventional","chinese":"威尔逊在他的新书中提出的观点被他视为极具其覆性， 但批评者却认为这些观点实际上相当传统。"},"p31r09":{"english":"Whether the director's action was pusillanimous or merely prudent & circumspect, the effect was the same: many board members argued against continuing to entrust leadership to a person who was perceived as unwilling to take risks.","chinese":"无论导演的行为是局弱还是谨慎， 结果都是一样的: 许多董事会成员反对继续将领导权交给一个被认为不愿冒险的人。"},"p31r10":{"english":"Leaders within the Native American culture known as Fort Ancient differed from those of the neighboring Mississippian groups, whose authority was oftencoercive & imperious_ indeed, one expert has described the Fort Ancient society as intensely egalitarian.","chinese":"在被称为堡垒古文化的美洲原住民文化中， 领导者与邻近的密西西比文化群体的领导者不同， 后者的权威通常是强制且专横的; 事实上， 有专家将堡垒古社会描述为高度平等主义。"},"p32r01":{"english":"Scientists are a generally anonymous & unrecognized_lot, but few can match in the depths of her perverse and unmerited obscurity the twentieth*century mathematical genius Amalie Noether.","chinese":"科学家通常是一个默默无闻且不被认可的群体， 但在她那种深刻的 、 荒恋且不应得的默默无闻中， 几乎无人能与 20 世纪数学天才阿玛莉 ` 诺特相匹敌。"},"p32r02":{"english":"The author engages the subject from diverse perspectives, supports his argument well with many examples, and manages to avoid antagonizing others in dealing with a verycontentious & controversial_subject.","chinese":"作者从多角度探讨主题， 用许多例子有力支持了他的论点， 并在处理一个极具争议性的话题时成功避免了引发对立。"},"p32r03":{"english":"The author's description of the ubiquitous & pervasive_contamination of ocean water with plastic materials -and the resulting threat to marine life-constitutes a valuable lesson in the urgency of managing trash more responsibly than we currently do.","chinese":"作者对海洋水体中塑料材料无处不在的污染及其对海洋生物造成威胁的描述， 传递了一个关于更负责任地管理垃圾的紧迫性的宝贵教训。"},"p32r04":{"english":"Since it is an incredible challenge to detect dark matter directly, scientists haveinferred & surmised_its existence from its gravitational effects on shaping galaxies and other large-scale structures.","chinese":"由于直接探测暗物质是一个极大的挑战， 科学家通过其对星系及其他大规模结构的引力效应推测其存在。"},"p32r05":{"english":"One object of examining past medical practices is to identify useful knowledge amid its now ‘outmoded trappings; the alternative is to let such knowledge fade & wane_along with the discredited theories with which it was associated.","chinese":"审视过去医疗实践的一个目的， 是在其现已过时的外壳中发现有用的知识; 另一种选择是让这些知识随着与之相关的失信理论一起消逝。"},"p32r06":{"english":"The late nineteenth century saw a shift in the production of African American history writing as works by lay & avocational_ authors came to be outnumbered by the publications of professional African American academics.","chinese":"19 世纪末， 非毅美国人历史写作的创作发生了转变， 专业非次美国学者的出版物逐渐超过了业余作者的作"},"p32r07":{"english":"The snow-covered surface of the lake presents a reassuring illusion of substantiality & soundness_, but beneath the snow the ice is riven with treacherous cracks.","chinese":""},"p32r08":{"english":"Williams argues that philosophy has become a recondite & an esoteric_ occupation these days, and that it should rather be part 5 1 1 1 2 8 254 56 13 12 96.924469 of 5 1 1 1 2 9 271 60 7 8 96.869629 a 5 1 1 1 2 10 283 60 33 8 93.375412 more 5 1 1 1 2 11 321 57 48 14 93.375412 general 5 1 1 1 2 12 374 58 51 13 96.268883 attempt 5 1 1 1 2 13 429 58 13 10 94.970284 to 5 1 1 1 2 14 447 57 36 11 92.752129 make 5 1 1 1 2 15 487 57 21 11 96.976746 the 5 1 1 1 2 16 512 57 28 11 96.901001 best 5 1 1 1 2 17 545 60 39 8 95.112709 sense 5 1 1 1 2 18 588 56 14 12 96.888451 of 5 1 1 1 2 19 606 60 21 8 70.837845 our 5 1 1 1 2 20 632 56 26 12 70.837845 life.","chinese":"威廉斯认为哲学如今已成为一种深奥且隐浅的职业， 而它本应是 \"更广泛尝试理解我们生活意义的一部"},"p32r09":{"english":"Epidemiological studies have found that occasional tea drinkers, and those who avoid tea altogether, do not reap the benefits of lowered risk of heart attack that those who swill & guzzle_ ‘the brew do.","chinese":"流行病学研究发现， 偶尔喝茶的人以及完全不喝茶的人无法获得经常冶饮茶饮者所享有的降低心脏病发作风险的蔓处。"},"p32r10":{"english":"The Holy People in Navajo sacred narratives do not act as moral paragons & exemplars_: when they teach, itis as often by what they do wrong as by what they do right.","chinese":"在纳瓦答神圣叙事中， 圣人并非道德典范: (HHNHWASEEREMIRTA, iB ETA"},"p33r01":{"english":"Critics have raved about the beauty of Pecks prose, but in his fiction, at least, the diction has only gotten more portentous with time, the writing more overwrought, and the symbolism more ungainly & awkward_.","chinese":"评论家们盛赞佩克的文笔之美， 但至少在他的小说中， 措辞随着时间的推移变得更加矫揉造作， 写作念发"},"p33r02":{"english":"The reader does well to approach claims in this autobiography with a certain amount of friendly skepticism, but the overall impression it conveys is that veracity wins out over invention & contrivance_.","chinese":"读者最好以一定程度的友好怀疑态度看待这本自传中的主张， 但整体印象是真实性胜过虚构。"},"p33r03":{"english":"The biographer laments the elisions & lacunae that abound in texts from antiquity; they are so prevalent, she says, that they nearly amount to a “conspiracy of silence’","chinese":"传记作者感叹古代文本中普遍存在的省略与空白; 她说， 这些现象如此普追， 几乎构成了一种 \"沉默的阴"},"p33r04":{"english":"Like his fellow itinerants & peripatetics_ covering the campaign tour, who rarely had the luxury of spending more than one night in one place, Tony had his bags packed well before the evening fund-raiser.","chinese":"像他的那些同行竞选活动中的游历者， 托尼和他们一样很少有机会在一个地方停留超过一晚， 化早在晚间募款活动之前就已经收拾好了行李。"},"p33r05":{"english":"Itis true that propagandists spout misinformation to serve their own ends, but if our minds were unreceptive to & inhospitable to_ such garbage, the lies would die out quickly.","chinese":"的确， 宣传者为了自身目的散布虚假信息， 但如果我们的思想对这些垃圾不接受且排斥， 这些谎言就会迅速消失。"},"p33r06":{"english":"While traditional Chinese historiography ostensibly described events in a neutral manner, early historians did not always eschew & forgo_tendentiousness, sometimes offering moral judgments about the historical figures they discussed.","chinese":"尽管传统的中国史学表面上以中立的方式描述事件， 早期的史学家并未完全握弃偏颇， 有时会对他们讨论的历史人物作出道德评判。"},"p33r07":{"english":"According to Waters, Cheryl Fishs otherwise brilliant analysis of Mary Seacole is marred & tainted_by a postmodern penchant for inventive jargon and fuzzy metaphysics.","chinese":"根据沃特斯的说法， 谢丽尔费什对玛丽 ' 西科尔的出色分析因后现代对创新术语和模糊形而上学的偏好而受"},"p33r08":{"english":"By avoiding hyperbole in her definitive account of one of the most influential but controversial banks of the modern era, Hurst shows herself to be a judicious & sensible_ author.","chinese":"通过在她对现代最具影响力但又充满争议的银行之一的权威叙述中避免夸张， 东斯特展现出自己是一位明智的作者。"},"p33r09":{"english":"One virtue of commeal as a component of the diets of laborers in early Puerto Rico was the mildness of its taste, a trait that enabled it to temper & neutralize_the strong flavors of other foods.","chinese":"玉米粉作为早期波多黎各劳动者饮食中的一种成分， 其优点之一是味道温和， 这一特性使其能够调和其他食物的浓烈味道。"},"p33r10":{"english":"In our solar system, Earth is the most sizable & substantial of the rocky, or terrestrial, planets, so when first searching beyond the solar system, scientists were not accustomed to planets of similar composition but many times the mass.","chinese":"在我们的太阳系中， 地球是岩石或类地行星中最庞大且坚实的， 因此当科学家首次在太阳系之外寻找时， 他们并不习惯于发现具有类似组成但质量是地球许多倍的行星。"},"p34r01":{"english":"‘The actor was quick to warn new members of the cast that the director's cherubic countenance belied a choleric & an irascible temperament.","chinese":"这位演员迅速淮告剧组的新成员， 导演天使般的面容掩盖了他暴踪易怒的性情。"},"p34r02":{"english":"The geometry student struggled with the request to demonstrate the patent & manifest proposition, feeling that, since opposite angles were self-evidently equal, there was no need for a proof.","chinese":"几何学生在展示显然命题时感到困难， 因为对他来说， 对项角显然相等， 因此无需证明。"},"p34r03":{"english":"The manufacturing company’ s swift maneuver enabled it to evade the full impact of the increasing cost of raw materials, which brought the downfall of firms that responded less deftly & adroitly.","chinese":"这家制造公司迅速的应对使其成功避开了原材料成本上涨的全面冲击， 而那些反应不够灵活的公司则因此倒闭。"},"p34r04":{"english":"Despite the critic’ s assertion that Willa Cather’ s place in the literary canon is now so entrenched that it scarcely matters if she were really a modernist, her reputation arguably remains uncertain & tenuous.","chinese":"尽管评论家上声称威拉 ' 凯瑟在文学经典中的地位如今已牢固到几乎无关她是否真的是现代主义者， 她的声誉可以说仍然不确定上且脆弱。"},"p34r05":{"english":"Pre-Columbian peoples had a significant impact on Amazonian forest diversity; at least 8,000 years ago, they must have begun domesticating plants recently found to be abundant & dominant around sites once occupied by humans.","chinese":"前哥伦布时期的人们对亚马逊森林的多祥性产生了重大影响; 至少在 8000 年前， 他们一定开始驯化植物， 而这些植物最近被发现如今在曾经有人类居住的遗址周围非常丰富且占主导地位。"},"p34r06":{"english":"Inhis article, Bazerman highlights Edison's brazen & barefaced manipulation of the press, including gifts of stock to friendly reporters.","chinese":""},"p34r07":{"english":"Hilton discusses the well-developed capacity among the most influential and talented Victorians for writing on a wide range of topics, thus highlighting their lordly disdain for & scorn for specialization.","chinese":"希尔顿讨论了最具影响力和才华的维多利亚时代人物在广泛主题上写作的高度能力， 从而突显了他们对专业化的傲慢轻茂。"},"p34r08":{"english":"Although initially it may be difficult to discern the essay's message of peace and conciliation, a close reading reveals its essentially pacific & dovish nature.","chinese":"尽管最初可能难以看出文章传递的和平与和解信息， 但仔细阅读后可以发现其本质上是温和的。"},"p34r09":{"english":"In the nineteenth century, the dish known as lobster Newburg was sometimes associated with the culinary accessory known as the chafing dish, but Welsh rarebit was considered the truly paradigmatic & archetypal chafing dish recipe.","chinese":""},"p34r10":{"english":"Despite the rather stringent & exacting conditions required for its preservation, the evidence for glaciation during the late Proterozoic is found on every continent, suggesting that ice sheets were present throughout the globe.","chinese":"尽管其保存需要相当严格的条件， 但晚期元古代冰川作用的证据在每个大陆都有发现， 这表明冰盖人遍布全"},"p35r01":{"english":"Globalization has made ethnic entrepreneurship resilient in postindustrial economies: well represented in the small business sector in the United States, ethnic entrepreneurship has been sustained & perpetuated by the volatile tides of international migration","chinese":"SERA CIE R LUE APRAMWE: 在美国的小企业领域中占有重要地位， 族裔创业因国际移民的动荡潮流而得以维持和延续。"},"p35r02":{"english":"Evolutionary psychologists hold that mating patterns arise from individual strategies to transmit & propagate one's genetic qualities, either by producing more offspring or by aiding the survival of one’s relatives.","chinese":"进化心理学家认为， 交配模式源于个体传递和传播自身基因特质的策略， 无论是通过繁衍更多后代， 还是通过帮助亲层的生存来实现。"},"p35r03":{"english":"Devoted to beauty and the poetic, evanescent moment, artists of the period were often inspired by the charm of the capital city and of its bucolic & rustic_ countryside.","chinese":"专注于美与诗意的阴间， 这一时期的艺术家常常受到首都城市及其田园乡村魅力的启发。"},"p35r04":{"english":"Modern historians’ silence on British views of French empire-building is perhaps explained, at least in part, by the paucity & scarcity of Victorian-era scholarship on pre-1870 French colonial enterprise.","chinese":"现代历史学家对英国人如何看待法国帝国建设的沉默， 或许至少部分可以用维多利亚时代关于 1870 年前法国殖民事业的研究 _ 稀缺 _ 来解释。"},"p35r05":{"english":"The current glut & surfeit of repackaged music under Miles Davis’ name might prompt any reasonable person to conclude that the recording vault has been plundered bare.","chinese":"目前以迈尔斯 ' 戴维斯之名重新包装的音乐泛滥， 可能会让任何理性的人得出录音库已被掏空的结论。"},"p35r06":{"english":"Very few companies take the trouble to discover where the wood in their products originates, consumers do not demand this information, and consequently indifference & apathy regarding illicit timber has become the norm.","chinese":"很少有公司费心去了解其产品中的木材来源， 消费者也不要求提供这些信息， 因此对非法木材的冷漠已成为常态。"},"p35r07":{"english":"Unlike mainstream publications, which centered on images of women as mothers and housewives, Sepia, from its inception in the 1940s, depicted women in varied & diverse roles and often featured stories of African American career women and entertainers.","chinese":"与主流出版物将女性形象集中于母亲和家庭主妇不同，Sepia 自 20 世纪 40 年代创刊以来， 就展现了女性在多样化角色中的形象， 并经常报道非麻美国职业女性和艺人的故事。"},"p35r08":{"english":"One can expect that future generations will steadily become lessitinerant & peripatetic_as new technologies enable the substitution of online activities for social, work and shopping-related travel.","chinese":"可以预期， 未来的世代将随着新技术使在线活动能够替代与社交 、 工作和购物相关的出行， 而逐潮变得不再流动。"},"p35r09":{"english":"Automated text: matching and plagiarism-detection services must be supplemented with & augmented by_ human expertise: machines alone cannot detect plagiarism of ideas, that is, expressing someone else's idea in one’s own words.","chinese":"自动化文本匹配和抄获检测服务必须辅以人工专业知识; 仅靠机器无法检测到思想抄袭， 即用自己的语言表达他人的想法。"},"p35r10":{"english":"Each of the country’s 26 sates and most of its more than 2,000 municipalities have their own police forces, [blank/] communication and making it difficult to establish a coordinated law- ‘enforcement strategy.","chinese":"该国的 26 个州和 2000 多个市镇各自拥有自己的警察部队， 缺乏沟通， 难以制定协调的执法策略。"},"p36r01":{"english":"During the Renaissance, the use of optical lenses, which were capable of projecting images onto blank canvases, greatly aided artists by allowing them to accurately observe and depict the external world; in other words, these lenses were instrumental in conveying realism & verisimilitude.","chinese":"在文艺复兴时期， 能够将图像投射到空白画布上的光学镜片极大地帮助了艺术家， 使他们能够准确地观察"},"p36r02":{"english":"Since some contemporary Western dieticians believe that the only function of food is to provide nourishment, these dieticians view an emphasis on the aesthetic dimension of the culinary arts as unwarranted & groundless.","chinese":""},"p36r03":{"english":"Noise suppression in phones can play an important role in making cellphone networks more efficient, since when sounds that are irrelevant & extraneous to the meaningful signal are transmitted, precious network band width is wasted.","chinese":"手机中的噪声抑制在提高蜂窝网络效率方面可以发挥重要作用， 因为当与有意义信号无关的多余声音被传输时， 会浪费宝贵的网络带宽。"},"p36r04":{"english":"The union states its position polemically; its leader say they are fighting to save good jobs while rapacious & avaricious corporations replace fulltime workers with part-time ones in order to cut down on both wages and benefits.","chinese":"工会以争论性的方式表明立场; 其领导人表示， 他们正在努力挽致优质工作， 而低焚的企业为了削减工资和福利， 将全职员工蔡换为兼职员工。"},"p36r05":{"english":"The Great Lakes wolf is a riddle & conundrum, stumping scientists as to whether it is a subspecies of the gray wolf or a distinct species.","chinese":""},"p36r06":{"english":"Itis hardly original & novel for today's film to try to blur the boundaries between the moral and the immoral. Hollywood has been doing that since at least the 1960s.","chinese":"今天的电影试图模糊道德与不道德之间的界限， 这几乎算不上新颖。 好莱坞至少从 20 世纪 60 年代开始就在这样做了。"},"p36r07":{"english":"Doris Kearns Goodwin's elegant, incisive study of Lincoln gratify & please those whose knowledge of Lincoln is an amalgam of high school history and popular mythology as well as those who are experts.","chinese":"及专家感到满意。"},"p36r08":{"english":"‘Anne Carson's book [iJNox{/i]is, very deliberately, a cumbersome & an unwieldy literary object— the opposite of an ereader which is designed to vanish in your palm as you read on a train.","chinese":"安妮. 卡森的书 《Nox》 是一个刻意制作的笨重文学作品一一与电子阅读器完全相反， 后者的设计是为了在你坐火车阅读时消失在掌中。"},"p36r09":{"english":"Far from spurring & fostering_ innovations, as the patent system was designed to do, the patenting of concepts such as gene sequences gives individuals and corporations a legal choke to hold over ideas that should be useful to all.","chinese":"非但没有激励和促进创新， 专利制度的设计初袁反而被扭曲， 基因序列等概念的专利化使个人和企业对本应为所有人所用的理念形成了法律上的茎断。"},"p37r01":{"english":"In Japanese aesthetics, especially but not only in Noh, beauty contains the idea of decay & deterioration: beauty must have an air of evanescence, the intimation of its own demise.","chinese":"ERARS+, KHER, PROSTRUMAS: 美必须带有一种转瞬即逝的气息， 以及自身消送的上暗示。"},"p37r02":{"english":"If giant X-ray flares churn circumstellar disks enough to keep newborn planets, such as Earth once was, from spiraling into their suns, it would be an ironic twist on our conception of X-ray flares as dangerous & perilous.","chinese":"如果巨大的 X 射线辉斑剧烈搅动环绕恒星的盘面， 从而阻止像地球曾经那样的新生行星螺旋附入它们的恒星， 这将碳获我们对 X 射线漆斑作为危险的认知。"},"p37r03":{"english":"Not only was this writer content to leave the reading public in the dark, she seems to have relished & delighted in the role of trickster, seeding her works with apparent clues that led nowhere.","chinese":"这位作家不仅甘愿让读者陷入迷茫， 还似乎乐在其中， 扮演着欺骗者的角色， 在作品中埋下了看似线索却毫无意义的内容。"},"p37r04":{"english":"His premiership, seemingly castiron year ago, is now so vulnerable that even a good day at the office does no more than buy him a few weeks of respite & relief from rebels within his own party.","chinese":"他的首相职位， 一年前似乎牢不可破， 如今却如此脆弱， 即使在办公室度过一个好日子， 也只能为他从党内叛乱者那里争取几周的喘息。"},"p37r05":{"english":"Mortoris is dour and lugubrious & gloomy, seemingly incapable of smiling, let alone laughing.","chinese":"莫托里斯性格阴沉 、 忧部， 似乎完全不会微笑， 更别提大笑了。"},"p37r06":{"english":"The preliminary analysis being on the whole, reassuring its confirmation would deflate & soothe concems about the dangers of project.","chinese":"初步分析总体上令人放心， 其确认将缓解对项目危险的担忧。"},"p37r07":{"english":"‘Some kinds of deadly bacteria, including those that cause tetanus, tuberculosis, and botulism, remain harmless & innocuous until something triggers their insidious activity.","chinese":"某些致命细菌， 包括引发破伤风 、 结核病和肉毒中毒的细菌， 在某些触发其隐秘活动之前， 始终是无害"},"p37r08":{"english":"Despite a tendency to be overtly preachy & sanctimonious, her poetry does not consist solely of pious sentiments: it often sparks the imagination and provides lively entertainment.","chinese":"尽管她的诗歌有时过于说教和伪善， 但并非仅仅充满虚诚的情感: 它常常激发想象力并带来生动的娱乐。"},"p37r09":{"english":"The town’s air was consistently malodorous & noisome_: depending on the breeze, one might be greeted with the sour effluvia of twenty breweries, choking fumes from the coal factory, or brackish smells from the nearby river.","chinese":"小镇的空气一贯恶臭: 根据风向， 人们可能会闻到二十家娠酒厂的酸味气息 、 煤厂的哈人烟雾， 或是附近河流的咸腥气味。"},"p37r10":{"english":"‘One of the vocalists who auditioned for a leading part in the local production of Sweeney Todd seemed to prefer shrieking & caterwauling to any attempt at producing a melody; a more unpleasant voice was hard to imagine.","chinese":"一位试镜本地版 《理发师陶德 》 主角的歌手似乎更喜欢尖叫适叫， 而不是尝试演唱旋律;很难想象还有比这更令人不锐的声音。"},"p38r01":{"english":"When studying the ancient Greek astronomers, Copernicus realized that despite the intrinsic beauty of many of their arguments, the ancients often made claims that defied & disregarded logic.","chinese":"在研究古希腊天文学家时， 哥白尼意识到， 尽管他们的许多论点本身具有内在的美感， 但古人常常提出一些违背逻辑的主张。"},"p38r02":{"english":"Films that critics have slumbered through rarely generate industry excitement, even though the critics’ somnolent & lethargic reception may be less the fault of the movie than of its unfortunate time slot near a fatiguing film festival's conclusion.","chinese":"段， 而非电影本身的过错。"},"p38r03":{"english":"Not only is the advent of bookless or largely bookless libraries too large and powerful a change to be averted & forestalled, it also offers too many real advantages for it to be considered a tragedy.","chinese":"不仅无书或几乎无书的图书馆的出现是一个过于巨大且强有力的变革， 无法阻止， 它还带来了太多实际的优势， 无法被视为一种悲剧。"},"p38r04":{"english":"The cat known to researchers as M-120—beefy, audacious, and apparently smart enough to spot a free lunch—is perhaps the world's least evasive & elusive lynx: the scientists catch him several times a year.","chinese":"被研究人员称为 M-120 的这只猫一一候壮 、 大胆， 而且显然足够聪明能发现免费的午餐一 -或许是世界上最不难捉摸的狂鲁: 科学家们每年都会抓到它好几次。"},"p38r05":{"english":"Since it was committed to the idea of science as an international, politically neutral enterprise, the Royal Society of London refused to expel & oust members from enemy nations during world wars of the twentieth century.","chinese":"由于致力于将科学视为一种国际性 、 政治中立的事业， 伦敦皇家学会在二十世纪的世界大战期间拒绝驱逐敌国成员。"},"p38r06":{"english":"The concert hall's suspended ceiling is two-inch-thick plaster that reflects low-frequency sound energy; similarly, all wall surfaces are angled and shaped to diffuse & spread sound from the stage throughout the audience area.","chinese":"音乐厅的悬吊天花板是两英寸厚的石膏板， 能够反射低频声音能量; 同样， 所有壤面都经过角度调整和设计， 以扩获声音并将其传递到整个观众区域。"},"p38r07":{"english":"Creativity is no longer seen as a momentary & an evanescent inspiration leading to poem or painting, it has come to be thought of as something permeating the whole of a person's life.","chinese":"创造力不再被视为短暂且转瞬即逝的灵右， 导致诗歌或绘画的诞生， 而是被认为贯穿于一个人整个生活的东西。"},"p38r08":{"english":"Investigating physiological irregularities & anomalies is not how biologists typically study function and structure, but it is not entirely unreasonable-if abnormalities in the lungs hinder breathing, then the lungs are very likely the organ required for breathing,","chinese":"研究生理异常是生物学家研究功能和结构的非典型方式， 但并非完全不合理 -一如果肺部的异常阻碍了呼吸， 那么肺部很可能是呼吸所需的器官。"},"p38r09":{"english":"Many great ghost stories remainambiguous & mute about the existence of their phantoms, whereas others leave no doubt about their ghosts reality.","chinese":"许多伟大的鬼故事对幽灵的存在保持 _ 模糊与沉默 _， 而另一些则毫不怀疑幽灵的真实性。"},"p38r10":{"english":"For more than 100 years, anarchism has been an embarrassing estranged sibling in the family of international radicalism, and its bad behavior had made it easy to dismiss & ignore the awkward but important questions anarchism poses.","chinese":"其提出的尴座但重要的问题。"},"p39r01":{"english":"Rosen argues that in the early years of the United States, individual states played important roles in the governance of American Indians, thereby belying & contradicting the common assumption that Indian policy was exclusively the federal government's domain.","chinese":"罗森认为， 在美国早期， 各州在管理美洲原住民方面发挥了重要作用， 从而驳斥了印第安政策完全层于联郑政府职权范围的普记假设。"},"p39r02":{"english":"Conchita evinceda proclivity for & an affinity for the arts: her favorite activities included visiting museums, attending plays or concerts, and reading poetry aloud.","chinese":"康奇塔表现出对艺术的热爱; 她最喜欢的活动包括参观博物馆 、 观看戏剧或音乐会， 以及朗读诗歌。"},"p39r03":{"english":"The book is impressivelyleamed & erudite, drawing from multiple disciplines and perspectives, and resting on diverse and extensive archival sources, autobiographies, published collections of letter, and works of history.","chinese":"这本书博学多识， 汲取了多个学科和视角的精华， 基于多样且广泛的档案资料 、 自传 、 已出版的书信集以及历史著作。"},"p39r04":{"english":"Potential readers may well be put off by the rather opaque quality of the prose in this book, which at times seems deliberately inaccessible to & insurmountable for the uninitiated reader.","chinese":"潜在谈者可能会被本书中相当几泌的文笔劝退， 这种文笔有时似乎是故意让外行读者难以理解且无法逾越"},"p39r05":{"english":"The potential reduction in water lost from the proposed reservoir from evaporation is scarcely & hardly inconsequential: even the minimum projected reduction would save enough water to furnish the needs of a Denver-sized municipality.","chinese":"从拟建水库蒸发中减少的潜在水量损失绝非微不足道: 即使是最低预计减少量， 也足以满足一个丹佛规模城市的用水需求。"},"p39r06":{"english":"Although a dedicated reader of the book can obtain & glean a brief of chronology of Chapelles life, the book is nevertheless not a real biography of Chapelle.","chinese":"尽管书的忠实读者可以从中获取简要的查佩尔生平年表， 但这本书仍然不是真正意义上的查佩尔传记。"},"p39r07":{"english":"Economic growth has been identified as a panacea & remedy for poor countries to eradicate poverty, but this prescription also triggers great environmental concerns.","chinese":"经济增长已被视为贫困国家消除贫困的灵丹妙药， 但这一处方也引发了巨大的环境担忧。"},"p39r08":{"english":"In mathematics, judgments about the validity of proofs are mediated by peer-reviewed journals; to ensure fairness & objectivity, reviewers are carefully chosen by journal editors, and the identity of scholars whose papers are under consideration are kept secret.","chinese":"在数学领域， 对证明有效性的判断通过同行评审期刊进行; 为了确保公正与客观， 期刊编辑会仔细挑选评审员， 并对正在审议的论文作者身份保密。"},"p39r09":{"english":"Any antimatter in our part of the universe is necessarily short-lived & ephemeral because of the overwhelming preponderance of ordinary matter, by which antimatter is quickly annihilated.","chinese":"在我们宇宙的这一部分， 任何反物质必然是短暂的， 因为普通物质的绝对优势会迅速潭灭反物质。"},"p39r10":{"english":"The phrase bread 5 1 1 1 1 4 160 45 23 11 93.594337 and 5 1 1 1 1 5 188 45 60 11 67.038956 circuses refers to early Roman politicians” plans to secure & earn the votes of the poor by handing out cheap food and entertainment.","chinese":"“面包和娱乐 \" 指的是早期罗马政治家通过分发廉价食物和娱乐来争取选民支持的计划。"},"p40r01":{"english":"The book reaffirms the idea that Africans on the continent have not stopped generating & originating or responding to their own creations; in fact, African creative agents have ushered in their own modem forms rooted in traditional ideas.","chinese":"这本书重申了这样一个观点; 非洲大陆上的非洲人从未停止创造或回应自己的创作;事实上， 非洲的创意主体已经在传统理念的基础上引入了属于他们自己的现代形式。"},"p40r02":{"english":"Flash floods are common in desert regions and were widespread before the evolution of trees and woodland soils; in contrast, flash floods are mitigated & abated in woodlands, where floodwaters, impeded by trees, form ponds.","chinese":"沙漠地区常见山洪暴发， 在树木和林地土壤出现之前尤为普遍; 相比之下， 在林地中， 山洪暴发被缓解， 洪水因树木阻挡而形成池塘。"},"p40r03":{"english":"Price knew about how to do people favors, sometimes just from kindness, but often out of self- interest & opportunism.","chinese":"普某斯懂得如何帮助别人， 有时是出于善意， 但更多时候是出于自私与投机。"},"p40r04":{"english":"Caricature can be revealing as well as amusing, and Agers novel is both: Agers delineation of class, ethnic, and generational struggle is exaggerated for comical effect, but it resonates & rings true nonetheless.","chinese":"漫画既能揭示真相又能带来趣味， 阿格的小说兼具两者: 阿格对阶级 、 族群和代际斗争的搓绘虽为喜剧效果而夺张， 但仍然真实动人。"},"p40r05":{"english":"Individuals interested in longevity have sought to fine-tune their bodies with all kinds of proscriptive & exacting diets: only raw foods; only plant; only the flesh, fruit, and nuts that prehistoric humans would have hunted and foraged.","chinese":"追求长寿的人尝试通过各种严格精细的饮食来调节身体: 只吃生食; 只吃植物; 只吃史前人类狩猎和采集的肉类 、 水果和坚果。"},"p40r06":{"english":"Even the man was reserved in his speech, he thoroughly understood his mother, which made him far from simple & ingenuous as people usually thought.","chinese":""},"p40r07":{"english":"Mark Messina’s book The Simple Soybean and Your Health exudes recognition much less unrestrained in the description of the soys medical efficiency than its versatility, but the author cautions against soy to be a cure-all & panacea","chinese":"马克. 梅西纳的 《简单大豆与您的健康 》 一书在描述大豆的医疗功效时远不如其多功能性那样训无保留， 但作者警告不要将大豆视为万能药。"},"p40r08":{"english":"Agencies responsible for protecting natural resources too often issue permits allowing exploitation of those resources, a process that remains obscure & opaque given that agencies have become experts at masking their decisions in the scientific terms.","chinese":"负责保护自然资源的机构经常颂发允许开发这些资源的许可证， 而这一过程由于机构擅长用科学术语掩盖其决策， 始终显得降涩难懂。"},"p40r09":{"english":"People enjoy listening to the governor's inspiring speeches, and his eloquence lulls his adversaries into underestimating his tenacity & resolve, the tempered steel beneath the sleek suits.","chinese":""},"p40r10":{"english":"Although many skeptics of the scientific theory recycle & rehash critiques that have long since been disproved, some of the doubters arguably bring up valid points.","chinese":"尽管许多科学理论的怀疑者重复旧有且早已被驱斥的批评， 但部分质疑者提出的观点可能确实有一定道"},"p41r01":{"english":"Although the employees’ union and company management, entering into contract negotiations, both issued statements encouraging civility & comity, acrimony between the two sides continued unabated.","chinese":"尽管员工工会和公司管理层在进行合同谈判时都发表声明， 呼吁文明和和谐， 但双方之间的争执仍然持续不断。"},"p41r02":{"english":"Upon realizing that the indicators of a stressful situation can be extremely exiguous & tenuous, the psychologist reconsidered her claim that a reliable way of reducing stress is to recognize stressful situations and then avoid them.","chinese":"当意识到压力情境的迹象可能极其微弱时， 心理学家重新考虑了她的观点， 即通过识别压力情境并加以避免是一种可靠的减压方法。"},"p41r03":{"english":"Sports stars are often totemic & emblematic figures, regarded as representative of the city or country for which they compete.","chinese":"体育明星往往是具有象征意义的人物， 被视为他们所代表城市或国家的代表。"},"p41r04":{"english":"The life of a secret agent is dangerous enough, but the life of a double agent is infinitely more precarious & perilous: a single slip can send an agent crashing to destruction","chinese":"秘密特工的生活已经足够危险， 但双面间谍的生活则更加寂发可和危: 一次失误就可能让特工陷入毁灭。"},"p41r05":{"english":"The writer's assignment of the critic includes personal aspersions & slurs such as jibes about his physical girth and style of delivery, and is not the better for it.","chinese":"作者对评论家的指责包括个人侮辱， 如嘲讽他的体型和表达方式， 这并无益处。"},"p41r06":{"english":"In the wild, no other mammal fosters & adopts individuals from another species: badgers do not tend hares, deer do not nurture baby squirrels, lions do not care for giraffes.","chinese":"在野外， 没有其他哺乳动物会收养异种个体: 猿不会照顾时免， 鹿不会养育幼松鼠， 狮子不会关心长颈"},"p41r07":{"english":"Although Lemettais was adept at & proficient in computer engineering, he lacked the spirit or enthusiasm to pursue it as a lifelong occupation","chinese":"尽管勒梅塔在计算机工程方面非常熟练， 但他缺乏将其作为终身职业的热情或动力。"},"p41r08":{"english":"The central idea of the worldview known as “consilience’ is that all tangible phenomena are based on material process that are ultimately reducible, however long and tortuous & convoluted the sequences, to the laws of physics.","chinese":"“ 融贯 \" 这一世界观的核心思想是， 所有有形现象都基于物质过程， 无论其过程多么曲折复杂， 最终都可以归结为物理定律。"},"p41r09":{"english":"Considering that space travel was science fiction only decades ago, we should be extremely reluctant to proclaim an idea forever technologically infeasible unless that idea violates & contravenes some hard physical constraint.","chinese":"非该想法违反某些严格的物理限制。"},"p41r10":{"english":"Patterson thought the waste leaking into the river was a pressing & an exigent situation: by contrast, judging from their silence on the matter, the owners of the factory felt the problem did not require immediate action.","chinese":"帕特森认为泄漏到河中的废物是一个紧迫的问题; 相比之下， 从工厂主对此事的沉默来看， 他们认为这个问题不需要立即采取行动。"},"p42r01":{"english":"‘Some historians represent the East India Company as a reluctant & an unwilling participant in political and military conflict in India, only taking an interest in territorial power and revenue as a last-ditch effort to protect its trading activities.","chinese":"一些历史学家将东印度公司描述为不情愿参与印度政治和军事冲突的角色， 仅在人迫不得已保护其贸易活动时才对领土权力和收入产生兴趣。"},"p42r02":{"english":"Scientists are investigating odors so faint that people cannot detect & discern them in order to. see whether such odors can nevertheless change the way people interact.","chinese":"科学家正在研究人类无法察觉的微弱气味， 以探究这些气味是否仍然能够改变人们的互动方式。"},"p42r03":{"english":"The spacecraft’s considerable heft forces an unusually circuitous & indirect route that meanders through the solar system and depends on the gravitational pull of three heavenly bodies.","chinese":"飞船的巨大重量迫使其采取一种异常还回的路线， 在太阳系中曲折前行， 并依赖三个天体的引力。"},"p42r04":{"english":"The apparent simplicity of savanna or a prairie landscape is illusory, but the illusion takes real effort to dispel & dismiss because much of what actually occurs in these places takes place underground.","chinese":"黎树草原或大草原景观表面上的简单性是种错觉， 但要打破这种错觉需要付出真正的努力， 因为这些地方的大部分活动实际上都发生在地下。"},"p42r05":{"english":"Considering how difficult it is to prove or disprove the existence of life on Mars, which is practically our neighbor, it is quite a formidable & a daunting challenge to do the same for any Earthlike planets that might exist outside our solar system.","chinese":"考虑到证明或否认火星上是否存在生命是多么困难， 而火星几乎是我们的邻居， 要对太阳系外可能存在的任何类地行星进行同样的探索， 无疑是一个极具挑战的任务。"},"p42r06":{"english":"The candidate seeks to depict his opponent as being inconstant & capricious, as one who is simply unable to make a decision and stand his ground.","chinese":"候选人试图将他的对手描绘成反复无常 、 难以决断且无法坚持立场的人。"},"p42r07":{"english":"Although his original mission was a failure, Russian botanist Michael Friedrich Adams achieved an unexpected triumph & success when he found, by chance, the carcass of a woolly mammoth.","chinese":"尽管他的最初任务失败了， 俄罗斯植物学家迈克尔. 弗里德里希. 亚当斯却意外地取得了成功， 当时他偶然发"},"p42r08":{"english":"Because experience had convinced her that Hector was both self-seeking and avaricious, she rejected the possibility that the motivation behind his donation had been wholly altruistic & benevolent.","chinese":""},"p42r09":{"english":"The 1840s were a favorable & an auspicious time for young women beginning to study science, particularly astronomy, in 1847 Maria Mitchell discovered the Nantucket comet, the first of several important astronomical discoveries of the era.","chinese":"19 世纪 40 年代是年轻女性开始学习科学， 特别是天文学的一个有利且吉祥的时期。1847 年， 玛丽亚: 米切尔发现了南塔克彗星， 这是该时代几项重要天文发现中的第一项。"},"p42r10":{"english":"To keep the museum's admission lines moving, security inspections are considerably cursory & casual","chinese":""},"p43r01":{"english":"Many people remember a time when cutting-edge architects, who are these days treated like celebrities, had an antagonistic & an inimical relationship with the public: for much of the 1960s, big new buildings in cities were often cause for hostility, not celebration.","chinese":"许多人记得曾经有一段时间， 人尖端建筑师一 -如今被视为名人一 -与公众之间存在敌对关系: 在 20 世纪 60 年代的大部分时间里， 城市中的大型新建筑往往引发敌意， 而非庆祝。"},"p43r02":{"english":"People from one community always take each other as kinfolk & relative since they automatically classify the others as their family line.","chinese":"一个社区的人总是将彼此视为亲层， 因为他们会自动将其他人归类为自己的家族成员。"},"p43r03":{"english":"The juxtaposition of fertile alluvial soils originating in the Andes with the infertile inland soils of central Amazon Basin is one example of heterogeneity & disparateness of the soil conditions that can be found in the tropics.","chinese":"例子。"},"p43r04":{"english":"He was one of the most powerful chess players over and one of the most perplexing & enigmatic; at the height of his fame he all but dropped out of chess, entering into a self-imposed exile.","chinese":"他曾是最强大的棋手之一， 也是最令人费解的; 在他声名部盛之时， 他几乎退出了棋坛， 进入了自我放逐的状态。"},"p43r05":{"english":"The women's rights movement has been mostly quiescent & abeyant in the Middle East, but it is likely that activists will be newly galvanized by the political upheavals currently sweeping the region.","chinese":"中东地区的女性权利运动大多处于沉训， 但当前席卷该地区的政治动荡可能会重新激励活动人士。"},"p43r06":{"english":"He was a man of few words, laconic & taciturn around all but his closest friends.","chinese":"他是一个寡言少语的人， 对除了最亲密的朋友以外的人都十分沉默。"},"p43r07":{"english":"There are many insights in the essay collected in Observations on modernity, but they are ‘embedded in a dense English translation of a dense German original that may make many of them inaccessible & opaque to most readers.","chinese":"《现代性观察 》 中的文章包含许多深刻见解， 但它们凡套在一篇睹浅的德文原著的复杂英文翻译中， 这可能使大多数读者难以理解且降涩。"},"p43r08":{"english":"Itis not unusual for American eduction leaders to hold up another nation as a model for school reform: in the mid-nineteenth century, such figures hailed & acclaimed the professionalism and structure of the Prussian school system.","chinese":"美国教育领导者将其他国家作为学校改革的典范并不罕见: 在 19 世纪中斯， 这些人物赞扬普鲁士学校系统的专业性和结构。"},"p43r09":{"english":"During the eighteenth century, improvements in their material circumstances did not necessarily mean expanded independence for women elite families and, arguably, the social conventions of gentility demanded & exacted more of their time and energy.","chinese":"在十八世纪， 物质条件的改善并不一定意味着精英家庭女性独立性的扩大， 可以说， 社交礼仪的规范要求她们付出更多的时间和精力。"},"p43r10":{"english":"Rebecca West's book Black Lamb and Grey Falcon is a singularity polymathic & encyclopedic achievement, 1,100 pages that meld the genres of travel narratives, autobiography, historical analysis, and philosophical meditation.","chinese":"丽贝卡. 韦斯特的 《 黑羊与灰应 》 是一部兼具博学与百科全书式成就的奇作， 全书长达 1100 页， 融合了游记 、 自传 、 历史分析和哲学沉思等多种体裁。"},"p44r01":{"english":"She expected her book to be controversial & provocative, but in fact few of her readers disagreed with its premise that street art, long considered a mere sideshow entertainment, deserved to be regarded as high art.","chinese":"她原以为她的书会引发争议且具有挑评性， 但实际上， 很少有读者不同意她的观点， 即街头艺术长期以来被认为只是次要的娱乐形式， 应该被视为高雅艺术。"},"p44r02":{"english":"Researchers have recorded around 60 separate behaviors for worker honeybees, a number that seems to eclipse & outdo the achievements of many mammals: even the versatile bottlenose dolphin only performs about twice the number a worker honeybee manages.","chinese":"研究人员记录了工蜂大约 60 种不同的行为， 这一数量似乎超越了许多哺乳动物的成就;: 即使是多才多艺的宽吻海豚， 其表现的行为也仅仅是工蜂的两倍左右。"},"p44r03":{"english":"Humanity's struggle with bedbugs is perennial & long-standing: archaeologists have recovered remains of the parasites dating back 3,500 years to the time of the Egyptian pharaohs.","chinese":"人类与皖虫的斗争是 ”长期存在且持久的 _: 考古学家已发现可追溯至 3500 年前埃及法老时期的寄生虫遗"},"p44r04":{"english":"The composer's string quartets exhibit a structural uncertainty & instability that seems to challenge the conventions of the string quartet genre, which have long been celebrated for their rigor and coherence.","chinese":"作曲家的该乐四重奏展现出一种结构上的不确定性， 似乎挑战了长期以来因严递与连贯性而备受推崇的弦乐四重奏传统。"},"p44r05":{"english":"Itis reprehensible & deplorable and rather, surprising, for someone with a considerable background in philosophy, that Taylor fails to distinguish adequately between forms of ‘communication and forms of knowledge.","chinese":"这是 _ 应受遗责且令人逮憾 ”的， 尤其令人惊讶的是， 作为一位具有相当哲学背景的人， 泰勒未能充分区分交流形式与知识形式。"},"p44r06":{"english":"As a proponent of women’s traditional roles, Sarah Hale was adamant against women's suffrage as thrusting women into an improper sphere; yet she supported & championed female textile strikers when they publicly protested their mistreatment at miles.","chinese":"作为女性传统角色的拥护者， 莎拉: 黑尔坚决反对女性选举权， 认为这会将女性推入不适当的领域; 然而， 她却支持并倡导女性纺织工人在工厂公开抗议章受的不公待遇。"},"p44r07":{"english":"Since Venus and Earth are so similar in their mass and density, Mueller suggested that the two planets have similar compositions and, therefore there must be surface features on Venus that have terrestrial counterparts & parallels.","chinese":"由于金星和地球在质量和密度上如此相似， 称勒提出两者具有相似的组成， 因此金星表面一定存在与地球相对应的特征。"},"p44r08":{"english":"Acloser examination of the author's footnotes explains the datedness of his argument: he has. ignore most of the recent work in the field, drawing instead mainly on research that is now decidedly obsolete & outmoded","chinese":"仔细审视作者的肢注可以看出其论点的过时之处: 他忽略了该领域的大部分最新研究， 而主要引用了如今显然已经陈旧的研究。"},"p44r09":{"english":"Although the Kuiper Belt—the icy region of the solar system where Pluto orbits—was once much more crowded, today it has such a low density of objects that collisions between them are improbable & unlikely.","chinese":"于它们之间的碰撞几乎不可能。"},"p44r10":{"english":"Of all the singer's works, this album is the most dependent on the musical conventions of her day; it was both the least experimental & innovative of her albums and the most commercially successful.","chinese":"在这位歌手的所有作品中， 这张专辑最依赖于她那个时代的音乐局例;) 它氏是她所有专辑中最不具实验性和创新性的， 也是商业上最成功的。"},"p45r01":{"english":"The environmental advocacy group pushed for a single, overarching wetlands management plan that would combine & meld the existing efforts of various entities, resulting in a focused blueprint for saving the area's wetlands.","chinese":"环保倡导组织推动制定一个统一的湿地管理计划， 以整合现有各方的努力， 形成一个专注于拯救该地区湿地的蓝图。"},"p45r02":{"english":"After the Turkish Republic was established, traditional hamams (bathhouses) seemed to many Turks to be outmoded, but thanks to tourism, hamams have experienced a revival & renaissance, becoming important cultural sites for foreign and Turkish visitors alike.","chinese":"在土耳其共和国成立后， 传统的土耳其浴 (澡堂 ) 在许多土耳其人看来似乎已经过时， 但由于旅游业的推动， 土耳其浴经历了复兴， 成为外国游客和土耳其人都重要的文化场所。"},"p45r03":{"english":"There is ample evidence that men and women think, express themselves, and even experience emotions differently, but in the area of sensory perception, psychologists are hard-pressed to identify major discrepancies & incongruities.","chinese":"难以发现显著差异。"},"p45r04":{"english":"The author advocates a diminished role for philosophy, aiming to show that many of the questions traditionally debated among philosophers can be ceded to & left to the realm of scientific inquiry.","chinese":""},"p45r05":{"english":"For wily political press officers, the art of spin is not quite supplanting truth with lies, but instead it aspires to replace awkward complexity with catchy simplicity & intelligibility; successful spin creates the impression of unavoidable common sense.","chinese":"对于狭独的政治新闻官来说， 操纵与论的艺术并非完全用谎言取代真相， 而是试图用引人注目的简洁明了 BRS AINBI SR; 成功的操纵会营造出不可避免的常识印象。"},"p45r06":{"english":"British composer Benjamin Britter would seem to have an assured & a settled place in the cultural pantheon, yet, at the same time that place is still contested by some.","chinese":"英国作曲家本杰了明. 布里顿似乎在文化巾堂中占据了稳固的位置， 但与此同时， 这一地位仍受到一些人的质"},"p45r07":{"english":"Compared with their parties, politicians are transitory & temporary: they are considerably less enduring than the organizations in which they function.","chinese":"与政党相比， 政治人物是短暂的: 他们的存在远不如其所服务的组织持久。"},"p45r08":{"english":"Unlike the theatrical adaptation of Nicholas Nickleby, which attempted to render & reproduce its source precisely, the adaption of Les Mislabels chooses sweeping and hurtling motion over the savoring of minute details.","chinese":"与试图精准呈现原作的 《尼古拉斯 ' 尼克贝 》 戏剧改编不同， 悲惨世界 》 的改编选择了宏大的气势与疾速"},"p45r09":{"english":"Our eating habits are rooted in our physiology, but they are also mediated by & influenced by the culture in which we grow up.","chinese":"我们的饮食习惯源于我们的生理， 但也受到我们成长所在文化的影响。"},"p45r10":{"english":"Climate change without the Arctic is a recognizedeatalyst for & factor in change elsewhere: around the world, ocean levels and daily weather are interconnected with the fortunes of a region that was, until recently, largely ignored.","chinese":"没有北极的气候变化是其他地方变化的公认催化剂: 全球范围内， 海洋水平和日常天气与一个直到最近才被广泛关注的地区的命运息息相关。"},"p46r01":{"english":"The use of retail coupons is commonly touted as a consumer benefit, discounting the price on an item; however, if the coupon relates to an item that the consumer neither needs nor wants, the discount is immaterial & irrelevant.","chinese":"使用零售优惠券通常被宣传为一种消费者福利， 可以降低商品价格; 然而， 如果优惠券涉及的是消费者既不需要也不想要的商品， 那么折扣就毫无意义。"},"p46r02":{"english":"As a publisher and a businessman, Guillaume Rouille was canny & shrewd_: he included a full set of portraits of the Ottoman Sultans in his encyclopedia to cater to the public thirst for information concerning the expanding empire of the Turks.","chinese":"FFAS A, 4O308-ER ERA: 他在自己的百科全书中加入了完整的奥斯曼帝国苏丹肖像， 以迎合公众对土耳其帝国扩张信息的温求。"},"p46r03":{"english":"","chinese":"#1931 FN—-BxSh, HR MRNA: “我们无法公开表达的内容， 通过音乐传达， 而我们所称的 ' 事士乐不仅仅是舞曲。"},"p46r04":{"english":"The problem a generation ago was not the new art itself but the heightened intensity of conviction surrounding it, which is thankfully absent in our wonderfully undogmatic & receptive_times.","chinese":"一代人之前的问题并非新艺术本身， 而是围绕它的强烈信念， 这种信念在我们如今极其开放且包容的时代已不复存在。"},"p46r05":{"english":"The somnolence & lethargy_of Craig's government had left the nation almost totally unprepared for war when it came,","chinese":""},"p46r06":{"english":"Japanese law draws a distinction between currency imitation and actual counterfeiting: only the latter involved an explicit intent to defraud & swindle__ the public.","chinese":"日本法律区分了货币仿制与真正伪造: 只有后者涉及明确的欺诈公众意图。"},"p46r07":{"english":"Singer Nina Simone in many ways defied categorization, with her artistic _hybridity & eclecticism__ evident in her early pieces that drew on disparate musical genres, including musical theatre, blues, and jazz standards.","chinese":"歌手妮娜.西蒙在许多方面都难以被归类， 她的艺术多样性在早期作品中显而易见， 这些作品融合了音乐剧 、 布鲁斯和问士经典等不同音乐风格。"},"p46r08":{"english":"Advertising’s role in popular music culture has been redefined: instead of a last resort for the creation and distribution of popular music, advertising now functions as a promoter & champion__of music that might otherwise go unheard.","chinese":"广告在流行音乐文化中的角色已被重新定义: 广告不再是流行音乐创作和传播的最后手段， 而是未被听到的音乐的推广者和拥护者。"},"p46r09":{"english":"Since beavers rely on auditory signals such as the tail slap and whining and hissing, we can infer that their hearing is functional & serviceable_, although we don't know the exact sensitivity and performance of their acoustical sense.","chinese":"我们并不了解它们听觉敏感度和性能的具体情况。"},"p46r10":{"english":"The auditors are relying on the failing bank to make changes that it has steadfastly resisted for years and even now does not seem keen & impatient & impatient_to carry out.","chinese":"审计人员依赖于这家濒临倒闭的银行进行其多年来始终拒绝的改革， 而该银行现在似乎仍不急于执行这些改革。"},"p47r01":{"english":"‘Some social insects, such as bees and ants, are celebrated for their industriousness and engineering feats, but popular culture has not generallyapplauded & extolled_termites for theirs— even though they can build mounds twenty feet high.","chinese":"一些社会性昆虫， 如窄蜂和蚂蚁， 以其勤劳和工程壮举而闻名， 但大众文化通常并未赞扬白蚁的成就 -一尽管它们能建造高达二十英尺的土丘。"},"p47r02":{"english":"The 1901 steel negotiations featured Morgan in his most famously histrionic & theatrical mode: knocking heads together, barking out prices for properties, and forcing titans to truckle to his will.","chinese":"1901 年的钢铁谈判中， 摩根以他最著名的戏剧性方式登场; SREP MUP, HSE EATER 于他的意志。"},"p47r03":{"english":"Coral reefs are often referred to as the rain forests of the sea, a fitting & an apposite_comparison given that only tropical rain forests can compete with the sheer concentration of biodiversity found in coral reefs.","chinese":""},"p47r04":{"english":"Despite their current reputation, the original Luddites were neither opposed to innovation technology nor inept at & unequal to_using it: many were highly skilled machine operators in the textile industry.","chinese":"尽管如今声名不佳， 最初的卢德分子并非反对创新技术， 也并非不擅长或无法使用这些技术: 许多人是纺织行业中技艺高超的机器操作员。"},"p47r05":{"english":"Despite much skepticism regarding & doubt about__ the county's political system, the fact that supporters failed in their attempts to change the constitution to allow the President to run again speaks well of the system's fundamental strengths.","chinese":"尽管对该县政治制度存在诸多怀疑， 但支持者未能成功修改宪法以允许总统再次参选， 这表明该制度具有基本的优势。"},"p47r06":{"english":"Ancient coins displayed in museums are almost by definition atypical & exceptional, on display precisely because they are the most beautiful, the most elaborate, and the best-preserved samples.","chinese":"博物馆中展出的古代钱币几乎可以说是非典型且卓越的， 正因为它们是最美丽 、 最精致 、 保存最完好的样本才被展示出来。"},"p47r07":{"english":"In the twentieth century, many corporations succeeded by eliminating & discontinuing innovation: they found that the surest way to grow was to perfect the manufacturing of the same products, year after year.","chinese":"在二十世纪， 许多公司通过消除创新成功: 他们发现， 增长的最可靠方式是年复一年地完善同类产品的制"},"p47r08":{"english":"When first introduced, cubicle workspaces were seen as having a liberating & an emancipatory effect on office workers, but as cubicle sizes steadily shrank, the aspirations of the people working in them became increasingly constrained.","chinese":"最初引入时， 隔间式工作空间被认为对办公室员工具有解放作用， 但随着隔间面积不断缩小， 员工的抱负也变得越来越受限。"},"p47r09":{"english":"Although workers are eager to believe rumors that the manufacturer plans to invest in modernizing the local plant, the troubled auto company has made no public commitment that Would illuminate & clarify the plant's future.","chinese":"尽管工人们急于相信和制造高计划投资于现代化改造当地工厂的传言， 但这家陷入困境的汽车公司并未公开承诺任何能够明确工厂未来的内容。"},"p47r10":{"english":"The convergence of two disparate sciences allows the imagining of new questions that cannot be addressed by knowledge and techniques sequestered within & unique to either field.","chinese":"两门截然不同的科学的融合使得人们能够想象出一些新的问题， 而这些问题无法通过任何一个领域独有的知识和技术来解决。"},"p48r01":{"english":"According to Peter Kwapong, rural Ghanaian farmers, despite regarding stingless bees as useful animals, by and large have not exploited & utilized the bees as economic resources.","chinese":"根据彼得克瓦翘的说法， 尽管加纳农村的农民将无剂蜂视为有用的动物， 但总体而言并未将其作为经济资源加以利用。"},"p48r02":{"english":"Despite a reputation, once richly deserved, for indolence & sloth in adopting new technologies, most big carmakers are pouring resources both into battery power and other alternative forms of propulsion, and into automated driving.","chinese":"尽管曾因在采用新技术方面的懒恬而声名在外， 但如今大多数大型汽车制造商正将资源投入到电池动力及其他蔡代驱动形式， 以及自动驾驶技术中。"},"p48r03":{"english":"One of the reporter's central themes is that health care concerns were a secondary consideration to the reformers in their drive to limit if not completely proscribe & disallow the consumption of cigarettes.","chinese":"记者的核心主题之一是， 在改革者努力限制甚至完全禁止吸烟的过程中， 健康问题只是次要考虑因素。"},"p48r04":{"english":"Despite growing evidence of a positive association between consumption of whole grains and long-term health, a research gap exists between observational studies and the elucidation of the mechanism involved, mechanisms that in some cases are still quitespeculative & unsubstantiated.","chinese":"尽管越来越多的证据表明全谷物消费与长期健康之间存在积极关联， 但观察性研究与机制闵明之间仍存在"},"p48r05":{"english":"Year after year, officials offer apparently sensible & levelheaded promises, so as to muster public support for ambitious engineering projects, but reality arrives years later in the form of outlandish expenditures and systems that fail to perform as promised.","chinese":"年复一年， 官员们提出看似理性承诺， 以争取公众对雄心勃勃工程项目的支持， 但几年后现实却以离谱的开支和未能如期运行的系统呈现。"},"p48r06":{"english":"In her new book, Alexander relates some amazing biological facts about the elephant—an elephant's heart can weigh 28.5 pounds, for example—but what really makes these behemoths remarkable is their continued survival despite more than a century of human predation & rapacity.","chinese":"在她的新书中， 亚历山大讲述了一些关于大象的惊人生物学事实 -一例如， 大象的心脏可以重达 28.5 磅一一但真正让这些庞然大物非凡的是它们在经历了一个多世纪的人类掠夺后仍然能够继续生存。"},"p48r07":{"english":"‘Some of the characters and themes depicted on the painted glass vessels found at Begram point toward an Egyptian provenance, but Egypt was not the sole & exclusive, and perhaps not even the principal place of manufacture.","chinese":"贝格拉姆发现的彩绘玻璃如四上描绘的一些人物和主题指向埃及起源， 但埃及并非唯一或主要的制造地， 甚至可能不是主要的生产地。"},"p48r08":{"english":"Margaret Oliphant’ literary output was ample & prodigious: it included almost 100 novels, 50 short stories, 25 nonfictional works, and in the region of 400 articles published in the periodical press.","chinese":"玛格丽特: 奥利芬特的文学创作十分丰富， 包含近 100 部小说 、50 篇短篇故事 、25 部非虚构作品， 以及约 400 篇发表在期刊上的文章。"},"p48r09":{"english":"Myth and orality are _interdependent & symbiotic__in Africa: the former is ubiquitous in the African oral literary tradition, while the latter is almost always based on the former.","chinese":"神话与口述在非洲是互相依存且共生的: 前者在非洲口头文学传统中无处不在， 而后者几乎总是以前者为基础。"},"p49r01":{"english":"To most ethicists, self-interested action connotes the opposite of moral conduct, and its abjuration & repudiation is for them a virtual prerequisite for serious ethical discourse.","chinese":"对大多数伦理学家而言， 自利行为意味着道德行为的对立面， 而其据弃是他们进行严肃伦理讨论的基本前"},"p49r02":{"english":"The effect of the distant past on an individual's financial decisions abates & dissipates much more slowly than the authors of the study had expected, with the impact of events early in life persisting decades into the future.","chinese":"遥远过去对个人财务决策的影响减弱得比研究作者预期的要慢得多， 早年事件的影响会持续数十年之久。"},"p49r03":{"english":"The film's pat and occasionally preposterous story is really just a contrivance & pretext, a serviceable scaffolding for a handful of expert, satisfying individual performances.","chinese":"这部电影情节简单且偶尔荒诞， 实际上只是一个巧合借口， 为几场精彩且令人满意的个人表演提供了一个实用的框架。"},"p49r04":{"english":"While most Centaurs (minor planets) are thought to bequiescent & dormant_, astronomers have observed patterns of brightening from the Centaur Chiron, as well as activity similar to that of a streaking comet.","chinese":"虽然大多数半人马小行星被认为是静止且休眠的， 天文学家观察到半人马星凯龙星的亮度变化， 以及类似蜀星划过时的活动迹象。"},"p49r05":{"english":"In general, the more that Victorian society felt it had lost contact with the rural, the more the rural became an object of idealization & romanticization_for metropolitan commentators, who represented it as a moral antidote to urban life.","chinese":"通常来说， 维多利亚社会越是感到与乡村失去了联系， 乡村就越成为都市评论者理想化与浪漫化的对象， 他们将其描绘为城市生活的道德解药。"},"p49r06":{"english":"The great jazz trumpeter John Birks Gillespie, who was saddled with the nickname Dizzy because of his onstageanties & capers_, was always considered a comparatively stable and reliable individual despite the nickname.","chinese":"伟大的事士小号手约翰, 伯克斯 - 吉莱斯皮因其舞台上的滑稽行为而被冠以 * 迪兹 \"的绰号， 尽管有这个绰号， 他一直被认为是一个相对稳定且可靠的人。"},"p49r07":{"english":"The artist’ s reputation remains somewhat marginal, a peripheral but persistent position that is perhaps just what she desires, since her art seeks a cult status that might beundermined & hampered_by her becoming too familiar.","chinese":"这位艺术家的声誉仍然有些边缘化， 处于一种外国但持久的地位， 这或许正是她所希望的， 因为她的艺术追求一种可能会因过于部悉而受损的崇拜地位。"},"p49r08":{"english":"The author's point is not that people should be dismissive of & scornful of science; he is careful to point out that what science is discovering about humans, for example, is certainly important and worthy of careful consideration.","chinese":"作者的观点并不是人们应该轻视科学; 他递慎地指出， 科学关于人类的发现， 例如， 确实重要且值得认真思考。"},"p49r09":{"english":"She had a feeling that was not yet fully articulated, an inchoate & an incipient_sense that something extraordinary and wonderful awaited her.","chinese":"她有一种尚未完全表达的感党， 一种初现的奇妙预感， 仿佛有非凡而美好的事情在等待着她。"},"p49r10":{"english":"Kelly Cherry's fiction speaks to various postmodern debates regarding history and perception, but does not become so abstract that the reader feels the narrative has beenceded to & surrendered to_an intellectual agenda.","chinese":"凯莉 ' 切里的小说涉及关于历史和感知的各种后现代讨论， 但并未抽象到让读者觉得叙事已屈从于智识议程的地步。"},"p50r01":{"english":"Millville has its share of suburban eyesores - cement-block strip malls, rows of fast-food restaurants, andbanal & lackluster_ split-level homes marching up hillsides denuded of trees.","chinese":"米尔维尔有一些郊区的碍眼之处一一水泥砖的商业街 、 成排的快父店， 以及毫无特色的分层住宅沿着被砍伐树木的山坡排列。"},"p50r02":{"english":"The chancellor once openly admired the relatively laissez-faire economic recipes of Britain and the United States but now defends the German way, in which she sees the free market's sometimes destructive vicissitudes being tempered & mitigated_by consensus-building politics and a generous welfare state.","chinese":""},"p50r03":{"english":"Partisans of literary realism sometimes think that because fantastical narratives do not abide by the laws of reality, they repudiate & repudiate & abjure_all rules, though, in fact, the logic of fairy tales is often relentlessly rigorous.","chinese":"文学现实主义的支持者有时认为， 幻想叙事因为不遵守现实法则， 就完全所弃所有规则， 然而实际上， 童话的逻辑往往极其严并。"},"p50r04":{"english":"Although the evidence to date is that the regime is not antithetical to & not opposed to_ freedom, this does not imply that any other regime would be more compatible with freedom: on the contrary, others are almost certain to be less so.","chinese":"尽管目前的证据表明该政权并非与自由对立或反对自由， 但这并不意味着其他政权会更符合自由; 相反， 其他政权几乎肯定会更不符合自由。"},"p50r05":{"english":"As the global climate warms, some deserts, expanding to higher latitudes, are beginning to displace & supplant_fertile regions.","chinese":"随着全球气候变暧， 一些沙漠开始向更高纬度扩展， 逐渐取代肥沃地区。"},"p50r06":{"english":"The wealth of insightful and challenging articles found in the journal is astounding in a world where mainstream publications increasingly focus on the most hackneyed & pedestrian_of topics.","chinese":"在一个主流出版物越来越关注最陈腐平庸话题的世界里， 这本期刊中充满洞见且富有挑战性的文章令人惊"},"p50r07":{"english":"Although the book, with its many and varied approaches to its subject, might strike some readers as too loosely structured, this refreshingly nonreductive method is commensurate with & appropriate for_the complexity of the issues the author explores.","chinese":"尽管这本书对其主题采用了多种多样的方式， 可能会让一些读者觉得结构过于松散， 但这种令人耳目一新的非简化方法与作者探讨问题的复杂性相称且适宜。"},"p50r08":{"english":"To help protect the environment, the United States government currently requires safe storage of coal ash for 30 years, “if feasible,” but many countries that burn coal lack even such discretionary","chinese":"为了保护环境， 美国政府目前要求在 “可行 \" 的情况下安全储存煤灰 30 年， 但许多燃烧国家甚至缺乏这样的基本环保措施。"},"p50r09":{"english":"The figure of Gertrude Stein endures & persists_: more than a hundred books about her have been written during the past decade or so, and recently she was depicted in a popular Hollywood film.","chinese":"格特鲁德.斯坦的形象经久不误: 过去十年左右关于她的书知已超过百本， 最近她还出现在一部热门好莱雹电影中。"},"p51r01":{"english":"Ina time when so much new concert music failed to speak to listeners, the composer's symphonies expressed withscathing & lacerating_wit and scorching emotional power the tragic history he lived through.","chinese":"在许多新音乐会作品无法打动听众的时代， 这位作曲家的交响曲以尖锐辛辣的机智和炽烈的情感力量表达了他所经历的悲惨历史。"},"p51r02":{"english":"Eglers prediction in 1947 that the introduction of mangrove trees to the Hawalian Islands would cause sweeping ecological change wasprescient & foresighted_: extensive mangrove forests have come to displace many preexisting plant communities.","chinese":"埃格勒在 1947 年的预测， 即红树林引入夏威夷群岛将引发广泛的生态变化， 确实非常有远见: 大片红树林已经取代了许多原有的植物群落。"},"p51r03":{"english":"Receiving sole credit for a scientific breakthrough is tantamount to acquiring a much-coveted prize: small wonder, then, that scientists often impugn & dispute_the claim of first discovery.","chinese":"将科学突破的唯一功劳归于自己无异于落得一个备受追摔的奖项: 难怪科学家们经常质疑这一首创权的主"},"p51r04":{"english":"Fedigan argues that, in actuality, ethologists who claim to eschew & avoid_anthropomorphism often end up simply substituting one set of anthropomorphic terms for another.","chinese":"费迪根认为， 实际上， 那些声称避免拟人化的动物行为学家往往只是用另一组拟人化术语来蔡代原有的术"},"p51r05":{"english":"Those who admired Callas felt that she was one of the greatest opera singers of all time, while others believed that her vocal inadequacies precluded & invalidated_such a claim.","chinese":"那些欣赏卡拉斯的人认为她是有史以来最伟大的歌剧歌手之一， 而另一些人则认为她的声乐缺陷使这一说法毫无根据。"},"p51r06":{"english":"China has a long tradition of venerating & exalting_ the written word; whereas in Renaissance Europe, painting, sculpture, and architecture were viewed as the apex of artistic achievement, in China calligraphy was the preeminent art form.","chinese":"中国有着尊崇书写传统的悠久历史; 而在文艺复兴时期的欧洲， 绘画 、 雕塑和建筑被视为艺术成就的冉峰， 在中国， 书法则是最卓越的艺术形式。"},"p51r07":{"english":"With its many islands, the Pacific Ocean had from early times been the habitat of nautical & maritime_civilizations-ones that had mastered the skills of sea travel.","chinese":"由于拥有众多岛屿， 太平洋自古以来就是航海文明的栖息地， 这些文明精通海上旅行的技能。"},"p51r08":{"english":"By and large, the writing of professional philosophers over the last century gets high marks for lucidity, though one can certainly point to a few whose prose is notably muddled & turbid_.","chinese":"总的来说， 过去一个世纪专业哲学家的写作因其清晰性而备受筑誉， 尽管确实可以指出一些人的文章明显"},"p51r09":{"english":"The writer had little interest in realism; many of his stories take place in a world either fancifully sketched out or purposefully mythical & enigmatic.","chinese":"作者对现实主义兴趣不大; 他的许多故事发生在一个充满幻想或刻意神秘的世界中。"},"p51r10":{"english":"The enigmatic & inscrutable markings on some prehistoric bone and antler fragments could be accidents or the result of doodling, but may also represent a form of communication such as tally marks or even early calendars.","chinese":"例如计数标记甚至早期的日历。"}};
